// Written by scripts/build-sat-bank.mjs. Do not edit by hand.
// Every SAT question. Read only by api/sat-bank.js; never import this from src/.
export const PRO_BANK = [{"id":"rw-wic-3","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"Early reviews of the novel were ______; critics could not agree on whether its unusual structure was brilliant or merely confusing.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["mixed","enthusiastic","absent","unanimous"],"answer":0,"explain":"Critics disagreed, so the reviews were mixed. \"Unanimous\" would mean they all agreed."},{"id":"rw-wic-4","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"Because the fossil was so ______, the researchers moved it only after wrapping it in layers of plaster and foam.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["fragile","recent","colorful","ordinary"],"answer":0,"explain":"Careful wrapping is needed for something easily broken: fragile."},{"id":"rw-wic-5","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"The engineer's explanation was admirably ______: in under two minutes, she made clear why the bridge had failed.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["concise","uncertain","evasive","tedious"],"answer":0,"explain":"Clear and short is concise. The word \"admirably\" rules out the negative choices."},{"id":"rw-wic-6","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"Jamdani weavers in Bangladesh work without printed patterns; instead, they ______ complex floral designs from memory, passing the motifs from one generation to the next.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["reproduce","conceal","purchase","abandon"],"answer":0,"explain":"Weaving known designs from memory means reproducing them."},{"id":"rw-wic-7","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"The city council expected the new bicycle lanes to be controversial, but public reaction was largely ______, with few residents expressing strong feelings either way.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["jubilant","indifferent","divided","hostile"],"answer":1,"explain":"\"Few strong feelings either way\" describes indifference. \"Divided\" would need strong feelings on both sides."},{"id":"rw-wic-10","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"The poet's later work ______ the ornate style of her youth: the long, decorated sentences give way to short lines of plain, everyday speech.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["imitates","abandons","exaggerates","perfects"],"answer":1,"explain":"The ornate style \"gives way\" to plain speech, so the later work leaves it behind."},{"id":"rw-wic-11","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"Historians once assumed the two ancient cities were rivals, but newly translated letters ______ that view, showing that their rulers regularly exchanged gifts and advice.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["predate","repeat","undermine","confirm"],"answer":2,"explain":"\"But\" signals a contrast: friendly letters weaken, or undermine, the idea of rivalry."},{"id":"rw-wic-12","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"The documentary refuses to ______ the decline in bee populations to any single cause; rather, it presents pesticides, disease, and habitat loss as interacting factors.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["prefer","adapt","attribute","contribute"],"answer":2,"explain":"To \"attribute X to a cause\" is to say the cause explains X. The other verbs do not fit \"to any single cause\"."},{"id":"rw-wic-13","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"In the 1920s, the mathematician's ideas were considered ______, of interest only to a handful of specialists; today they underlie the encryption that protects everyday online purchases.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["practical","dangerous","obscure","popular"],"answer":2,"explain":"Ideas known only to a few specialists are obscure. The sentence contrasts this with their wide use today."},{"id":"rw-wic-14","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"The two species of finch look nearly identical, yet their songs are ______: even an untrained listener can tell them apart after a few seconds.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["similar","distinct","borrowed","faint"],"answer":1,"explain":"\"Yet\" contrasts looks with songs: the songs are easy to tell apart, so they are distinct."},{"id":"rw-wic-16","section":"rw","domain":"cs","skill":"wic","level":3,"type":"mc","passage":"Critics who call the architect's buildings cold overlook how ______ they are to their surroundings: each one is oriented to catch local winds and is built from stone quarried nearby.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["indifferent","attuned","identical","superior"],"answer":1,"explain":"Buildings shaped by local wind and stone are well adjusted, or attuned, to their surroundings."},{"id":"rw-wic-17","section":"rw","domain":"cs","skill":"wic","level":3,"type":"mc","passage":"The essayist's praise of small-town life is not ______; she acknowledges the limited opportunities and lack of privacy even as she celebrates the sense of belonging.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["unqualified","sincere","original","deliberate"],"answer":0,"explain":"\"Unqualified\" means without reservations. Her praise comes with reservations, so it is not unqualified."},{"id":"rw-wic-18","section":"rw","domain":"cs","skill":"wic","level":3,"type":"mc","passage":"Rather than ______ earlier theories of memory, the new model incorporates them, treating each as a correct description of one stage in a longer process.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["supplanting","combining","extending","honoring"],"answer":0,"explain":"\"Rather than\" needs the opposite of incorporating: replacing, or supplanting."},{"id":"rw-wic-19","section":"rw","domain":"cs","skill":"wic","level":3,"type":"mc","passage":"The treaty's language was so ______ that each government could plausibly claim it had won the concessions it wanted.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["ambiguous","brief","precise","hostile"],"answer":0,"explain":"Wording that supports opposite readings is ambiguous. Precise wording would allow only one."},{"id":"rw-wic-20","section":"rw","domain":"cs","skill":"wic","level":3,"type":"mc","passage":"Although the chemist's method is ______ (it requires no special equipment and only three inexpensive ingredients), it yields crystals as pure as those produced in advanced laboratories.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["rudimentary","obsolete","elaborate","hazardous"],"answer":0,"explain":"A method with no special equipment is basic, or rudimentary. \"Although\" contrasts that with its excellent results."},{"id":"rw-tsp-3","section":"rw","domain":"cs","skill":"tsp","level":1,"type":"mc","passage":"Each January, residents of Old Dhaka celebrate Shakrain, a festival marking the end of the Bengali month of Poush. From afternoon until dusk, rooftops fill with families flying kites, and neighbors compete to cut one another's kite strings.","question":"Which choice best describes the overall structure of the text?","options":["It compares two festivals, then explains which is older.","It describes a problem, then proposes a solution.","It introduces a tradition, then describes how it is celebrated.","It presents a claim, then offers evidence against it."],"answer":2,"explain":"Sentence one names the festival; sentence two shows what people do during it."},{"id":"rw-tsp-4","section":"rw","domain":"cs","skill":"tsp","level":1,"type":"mc","passage":"Honeybees perform a \"waggle dance\" to tell their hive-mates where food is. The angle of the dance shows the direction of the flowers relative to the sun, and its length shows the distance.","question":"Which choice best describes the function of the second sentence in the text as a whole?","options":["It gives an example of an animal that does not behave this way.","It questions whether the behavior named in the first sentence really occurs.","It explains how the behavior named in the first sentence conveys information.","It describes how scientists first discovered the behavior."],"answer":2,"explain":"The second sentence says what the angle and the length of the dance mean."},{"id":"rw-tsp-7","section":"rw","domain":"cs","skill":"tsp","level":2,"type":"mc","passage":"Urban planners in several cities have replaced asphalt playgrounds with gardens and trees. Supporters point to lower summer temperatures and less flooding. Maintenance crews, however, note that living landscapes require regular care that budgets do not always cover.","question":"Which choice best describes the function of the third sentence in the text as a whole?","options":["It introduces a practical concern about the change described earlier.","It summarizes the benefits listed in the previous sentence.","It explains why planners first proposed the change.","It offers a second example of the change."],"answer":0,"explain":"\"However\" turns from benefits to a difficulty: the cost of upkeep."},{"id":"rw-tsp-8","section":"rw","domain":"cs","skill":"tsp","level":2,"type":"mc","passage":"My grandmother never said she missed the village. But every evening she stood at the window facing east, and when I asked what she was looking at, she would say only, \"The weather.\"","question":"Which choice best states the main purpose of the text?","options":["To explain why a family moved to a city","To suggest a feeling that a character does not state directly","To describe the weather in a particular village","To show a disagreement between two characters"],"answer":1,"explain":"She never says she misses the village, but her nightly habit shows it."},{"id":"rw-tsp-10","section":"rw","domain":"cs","skill":"tsp","level":3,"type":"mc","passage":"The glassmaker's studio contains no finished pieces. She sells or gives away each one within days, keeping only the failures: a bowl that cracked while cooling, a vase that leaned. \"The good ones have nothing left to teach me,\" she explains.","question":"Which choice best states the main purpose of the text?","options":["To argue that failed artworks are worth more than successful ones","To convey an artist's unusual attitude toward her own work","To explain the steps involved in making glass","To describe how an artist sets prices for her pieces"],"answer":1,"explain":"The text shows one artist's view. It does not make a general argument about all art."},{"id":"rw-tsp-11","section":"rw","domain":"cs","skill":"tsp","level":3,"type":"mc","passage":"It is tempting to read the diary as a plain record of events. But its author revised it for years, cutting some entries and expanding others, with an eye to publication. What survives is less a window onto her days than a portrait she composed of herself.","question":"Which choice best describes the overall structure of the text?","options":["It describes how a document was lost and later found.","It warns against one way of reading a document, gives a reason for the warning, and offers another way of understanding the document.","It summarizes a document, praises its honesty, and recommends it to readers.","It contrasts the diaries of two different authors."],"answer":1,"explain":"\"It is tempting... But... What survives is...\" follows warning, reason, new view."},{"id":"rw-tsp-12","section":"rw","domain":"cs","skill":"tsp","level":3,"type":"mc","passage":"Lichens grow so slowly, often less than a millimeter a year, that their size can serve as a clock. By measuring the largest lichens on a rock surface exposed by a retreating glacier, geologists can estimate how long ago the ice withdrew. The method fails, however, where pollution or shade has stunted growth.","question":"Which choice best describes the function of the last sentence in the text as a whole?","options":["It explains why lichens grow slowly.","It restates the main advantage of the technique.","It identifies conditions under which the technique described is unreliable.","It introduces a different technique that has replaced the one described."],"answer":2,"explain":"\"The method fails, however, where...\" names the limits of the method."},{"id":"rw-ctc-5","section":"rw","domain":"cs","skill":"ctc","level":2,"type":"mc","passage":"Text 1\nCity trees lower summer temperatures and should be planted as widely as possible.\n\nText 2\nPlanting trees helps a city only if the trees survive. Many newly planted street trees die within five years when no one is assigned to water them.","question":"Based on the texts, both authors would most likely agree with which statement?","options":["Most street trees die within five years.","The cost of maintaining trees outweighs their benefits.","Cities already have too many trees.","Trees are capable of benefiting cities."],"answer":3,"explain":"Text 1 states the benefit; Text 2 accepts it (\"helps a city\") while adding a condition."},{"id":"rw-ctc-7","section":"rw","domain":"cs","skill":"ctc","level":3,"type":"mc","passage":"Text 1\nThe printing press, a historian writes, transformed Europe almost at once, turning a continent of listeners into a continent of readers.\n\nText 2\nRecords suggest that for two centuries after the press appeared, the share of Europeans who could read rose only slowly. The sharpest increases came later, where villages opened schools.","question":"Based on the texts, how would the author of Text 2 most likely respond to the historian in Text 1?","options":["By claiming that schools made printed books unnecessary","By denying that the printing press was ever widely used","By agreeing that literacy became nearly universal within a generation","By arguing that the press alone does not explain the spread of reading, which was gradual"],"answer":3,"explain":"Text 2 says reading spread slowly and credits schools, against \"almost at once\"."},{"id":"rw-ctc-8","section":"rw","domain":"cs","skill":"ctc","level":3,"type":"mc","passage":"Text 1\nA biologist proposes that zebras evolved stripes to confuse predators: a moving herd becomes a blur in which no single animal stands out.\n\nText 2\nIn field experiments, horses dressed in striped coats were bitten by far fewer flies than horses in plain coats. Observations of lions, meanwhile, showed no difference in hunting success against striped and unstriped prey.","question":"Based on the texts, how would the author of Text 2 most likely respond to the proposal in Text 1?","options":["By claiming that flies are attracted to striped surfaces","By arguing that zebras are not hunted by predators","By agreeing that stripes mainly protect zebras from lions","By suggesting that the stripes more likely serve a different function from the one proposed"],"answer":3,"explain":"The evidence points to protection from flies and finds no effect on lions."},{"id":"rw-cid-3","section":"rw","domain":"ii","skill":"cid","level":1,"type":"mc","passage":"When the library reopened after the flood, the staff expected visitors to ask first about damaged books. Instead, the most common question was whether the reading room's old wooden tables had survived. They had, and regulars went straight to their usual seats.","question":"According to the text, what did visitors most often ask about?","options":["The library's new opening hours","The books damaged by the flood","The cause of the flood","The reading room's wooden tables"],"answer":3,"explain":"\"The most common question was whether the... wooden tables had survived.\""},{"id":"rw-cid-4","section":"rw","domain":"ii","skill":"cid","level":1,"type":"mc","passage":"A sourdough starter is a mixture of flour and water in which wild yeast and bacteria live. Fed regularly, it can last for decades; some bakeries use starters begun over a century ago.","question":"Which choice best states the main idea of the text?","options":["Most bakeries replace their starters every year.","Sourdough bread is healthier than other bread.","Wild yeast is difficult to find.","A properly maintained sourdough starter can be kept alive for a very long time."],"answer":3,"explain":"Both sentences build to the point about how long a fed starter lasts."},{"id":"rw-cid-7","section":"rw","domain":"ii","skill":"cid","level":2,"type":"mc","passage":"Every spring my father repainted the boat, though it had not touched water in ten years. He sanded the hull, chose the same blue, and wrote the name again in careful white letters. When he finished he would stand back, nod, and cover it with the tarp.","question":"Which choice best states the main idea of the text?","options":["The narrator's father faithfully maintains a boat he no longer uses.","The narrator's father is learning how to paint.","The narrator and his father disagree about the boat's color.","The narrator's father is preparing to sell his boat."],"answer":0,"explain":"He repaints it every year although it has not been in the water for a decade."},{"id":"rw-cid-8","section":"rw","domain":"ii","skill":"cid","level":2,"type":"mc","passage":"Plants cannot flee from insects, but many are far from defenseless. When caterpillars chew the leaves of a tomato plant, the plant releases chemicals into the air. Neighboring tomato plants detect these chemicals and begin producing substances that make their own leaves harder to digest.","question":"Which choice best states the main idea of the text?","options":["Chemicals released by plants are harmful to neighboring plants.","Tomato plants can respond to signals from damaged neighbors by strengthening their own defenses.","Tomato plants are unable to defend themselves against insects.","Caterpillars prefer tomato plants to all other plants."],"answer":1,"explain":"The neighbors detect the airborne chemicals and toughen their own leaves."},{"id":"rw-cid-10","section":"rw","domain":"ii","skill":"cid","level":3,"type":"mc","passage":"When the linguist began recording the village's language, only eleven fluent speakers remained. She expected grammar to be the hardest thing to document. In fact, the speakers explained grammar readily; what proved elusive were the names of plants, since the forest where many of those plants grew had been cleared decades earlier.","question":"According to the text, why were plant names difficult to document?","options":["The language's grammar was too complex.","Many of the plants were no longer present in the speakers' surroundings.","The linguist was not allowed to visit the village.","The speakers refused to share them."],"answer":1,"explain":"The forest where the plants grew \"had been cleared decades earlier\"."},{"id":"rw-cid-11","section":"rw","domain":"ii","skill":"cid","level":3,"type":"mc","passage":"Economic historians often date the invention of the weekend to factory schedules of the early twentieth century. But market towns had long observed informal rest days, and many workers simply stayed home on Mondays, a custom employers resented but tolerated. The factory weekend, then, did less to create leisure than to move it to days that owners could plan around.","question":"Which choice best states the main idea of the text?","options":["Workers had no leisure time before the twentieth century.","The modern weekend reorganized an existing habit of rest rather than inventing leisure.","Market towns adopted the weekend before factories did.","Factory owners opposed giving workers any days of rest."],"answer":1,"explain":"The last sentence states it: the weekend moved leisure rather than creating it."},{"id":"rw-cid-12","section":"rw","domain":"ii","skill":"cid","level":3,"type":"mc","passage":"Anwar had been praised all his life for being agreeable. He agreed with his teachers, with his brothers, with the men at the tea stall. It was only at forty, asked by his daughter what he himself thought about anything at all, that he noticed the silence where an answer should have been.","question":"Which choice best states the main idea of the text?","options":["A daughter criticizes her father for being disagreeable.","A man realizes that a lifelong habit of agreeing has left him without opinions of his own.","A man decides to stop visiting the tea stall.","A man regrets arguing with his family and friends."],"answer":1,"explain":"His daughter's question shows him he has no answer of his own."},{"id":"rw-coe-3","section":"rw","domain":"ii","skill":"coe","level":1,"type":"mc","passage":"A teacher claims that students remember vocabulary better when they test themselves than when they reread their notes.","question":"Which finding, if true, would most directly support the teacher's claim?","options":["Most students owned a vocabulary notebook.","Students who reread their notes studied for the same amount of time.","A week later, students who tested themselves recalled 80% of the words, while students who reread recalled 55%.","Students said that rereading notes felt easier than testing themselves."],"answer":2,"explain":"It compares recall for the two methods, which is exactly what the claim is about."},{"id":"rw-coe-4","section":"rw","domain":"ii","skill":"coe","level":1,"type":"mc","passage":"A critic argues that the film's greatest strength is its music rather than its story.","question":"Which quotation from a review of the film most directly supports the critic's argument?","options":["\"The music is pleasant but easy to forget.\"","\"The story builds to a satisfying finish.\"","\"The plot wanders, but the score carries every scene.\"","\"The actors do what they can with thin dialogue.\""],"answer":2,"explain":"It praises the music and faults the story, matching the claim."},{"id":"rw-coe-5","section":"rw","domain":"ii","skill":"coe","level":1,"type":"mc","passage":"A librarian recorded how many books were borrowed in the first three months of the year. Borrowing rose steadily over the period, ______","table":{"head":["Month","Books borrowed"],"rows":[["January","120"],["February","150"],["March","210"]]},"question":"Which choice most effectively uses data from the table to complete the statement?","options":["with February the busiest month.","from 120 books in January to 210 in March.","reaching 150 books in March.","from 210 books in January to 120 in March."],"answer":1,"explain":"The table shows 120, then 150, then 210: a steady rise."},{"id":"rw-coe-8","section":"rw","domain":"ii","skill":"coe","level":2,"type":"mc","passage":"A company claims that its new keyboard layout lets people type faster than the standard layout does.","question":"Which finding, if true, would most weaken the company's claim?","options":["After four weeks of practice, typists using the new layout were no faster than typists using the standard layout.","On their first day, typists using the new layout made more errors.","Some typists said they liked the appearance of the new keyboard.","The new keyboard costs more than a standard keyboard."],"answer":0,"explain":"Equal speed after real practice directly contradicts \"faster\". First-day errors say little about speed once learned."},{"id":"rw-coe-9","section":"rw","domain":"ii","skill":"coe","level":2,"type":"mc","passage":"A historian claims that the port city's wealth in the 1600s depended chiefly on the spice trade.","question":"Which finding, if true, would most directly support the historian's claim?","options":["Tax records from the period show that duties on pepper and cloves made up three-quarters of the city's income.","Merchants in the city also traded cloth and timber.","Paintings from the period show ships in the city's harbor.","The city's population doubled during the 1600s."],"answer":0,"explain":"Three-quarters of income from spices shows the city depended chiefly on them."},{"id":"rw-coe-10","section":"rw","domain":"ii","skill":"coe","level":2,"type":"mc","passage":"In a sleep study, volunteers' reaction times were measured after nights of different lengths. Less sleep slowed reactions, but the effect was not proportional: ______","table":{"head":["Sleep","Average reaction time"],"rows":[["8 hours","250 ms"],["6 hours","270 ms"],["4 hours","330 ms"]]},"question":"Which choice most effectively uses data from the table to complete the statement?","options":["cutting sleep from 8 hours to 6 slowed reactions by 20 milliseconds, while cutting it from 6 hours to 4 slowed them by a further 60.","cutting sleep from 8 hours to 6 slowed reactions by 60 milliseconds.","volunteers who slept 8 hours reacted in 330 milliseconds.","volunteers who slept 4 hours reacted fastest."],"answer":0,"explain":"250 to 270 is a rise of 20; 270 to 330 is a rise of 60. The second loss of two hours cost three times as much."},{"id":"rw-coe-12","section":"rw","domain":"ii","skill":"coe","level":3,"type":"mc","passage":"An agricultural researcher applied different amounts of fertilizer to five plots and concluded that fertilizer raises yield only up to a point: ______","table":{"head":["Fertilizer","Yield"],"rows":[["0 g","20 kg"],["10 g","28 kg"],["20 g","33 kg"],["30 g","33 kg"],["40 g","29 kg"]]},"question":"Which choice most effectively uses data from the table to complete the statement?","options":["the plot given no fertilizer produced no yield.","yield was highest on the plot given 40 g of fertilizer.","yield rose from 20 kg with no fertilizer to 33 kg with 20 g, did not rise further with 30 g, and fell to 29 kg with 40 g.","yield rose from 20 kg with no fertilizer to 28 kg with 10 g."],"answer":2,"explain":"To show \"only up to a point\" the data must include both the rise and the levelling off and fall."},{"id":"rw-coe-13","section":"rw","domain":"ii","skill":"coe","level":3,"type":"mc","passage":"A psychologist argues that people value an object more when they have put effort into making it, even if the result is poor.","question":"Which finding, if true, would most directly support the psychologist's argument?","options":["Participants offered to pay more for large boxes than for small ones.","Participants said they preferred boxes built by experts.","Participants who assembled a wobbly box themselves offered to pay more for it than other participants offered for a neatly finished box of the same design.","Participants who assembled their boxes quickly rated the task as easy."],"answer":2,"explain":"A higher value on a worse box, made by oneself, is the effect being claimed."},{"id":"rw-coe-14","section":"rw","domain":"ii","skill":"coe","level":3,"type":"mc","passage":"Researchers claim that a seabird colony declined because warmer water drove its main prey fish deeper, beyond the birds' diving range.","question":"Which finding, if true, would most weaken the researchers' claim?","options":["A second seabird species, which eats different prey, did not decline.","Water temperatures near the colony rose by two degrees.","Throughout the decline, examination of the birds' stomachs showed they were catching as many of the prey fish as before.","The prey fish were recorded at greater depths than in earlier decades."],"answer":2,"explain":"If the birds still caught as many fish, loss of access to prey cannot explain the decline. The other findings fit the claim."},{"id":"rw-inf-3","section":"rw","domain":"ii","skill":"inf","level":1,"type":"mc","passage":"The bakery sells out of bread by 9 a.m. every day, and customers who arrive later often leave empty-handed. Yet the owner cannot bake more, because her oven is already full at every firing. To sell more bread, therefore, she would most likely need to ______","question":"Which choice most logically completes the text?","options":["raise the price of each loaf.","obtain a larger or an additional oven.","advertise to attract more customers.","open the bakery later in the day."],"answer":1,"explain":"The limit is oven space, so more bread requires more oven capacity."},{"id":"rw-inf-4","section":"rw","domain":"ii","skill":"inf","level":1,"type":"mc","passage":"Clay tablets from an ancient city record thousands of sales of grain and list precise values for goods, yet they never mention coins, and archaeologists have found no coins at the site. The most reasonable conclusion is that the city's inhabitants ______","question":"Which choice most logically completes the text?","options":["did not trade with one another.","had a way of measuring value that did not rely on coins.","could not read or write.","used coins that looked like those of today."],"answer":1,"explain":"Precise values without coins point to another system of measuring worth."},{"id":"rw-inf-7","section":"rw","domain":"ii","skill":"inf","level":2,"type":"mc","passage":"Visitors to a fair were asked to guess the weight of an ox. Individual guesses varied widely, but the average of all the guesses was within one percent of the true weight. The result implies that the errors in individual judgments ______","question":"Which choice most logically completes the text?","options":["were caused by dishonest guessers.","tended to cancel one another out when combined.","were all in the same direction.","grew larger as more people guessed."],"answer":1,"explain":"A very accurate average from scattered guesses means the highs and lows balanced."},{"id":"rw-inf-8","section":"rw","domain":"ii","skill":"inf","level":2,"type":"mc","passage":"A museum found that visitors spent an average of 20 seconds at paintings labeled with long explanations and 45 seconds at paintings labeled with a single question, such as \"What is the woman looking at?\" The museum concluded that if it wants visitors to look longer, ______","question":"Which choice most logically completes the text?","options":["it should display fewer paintings of people.","labels that invite visitors to investigate may work better than labels that explain.","it should remove the labels from all paintings.","longer explanations are needed."],"answer":1,"explain":"Question labels held attention more than twice as long as explanations."},{"id":"rw-inf-10","section":"rw","domain":"ii","skill":"inf","level":3,"type":"mc","passage":"A town's records for 1740 list twelve bakers but only one miller. Bread requires flour, and a single mill of that era could not have ground enough for twelve bakeries. The town therefore most likely ______","question":"Which choice most logically completes the text?","options":["had far fewer residents than the records suggest.","ate little bread.","obtained much of its flour from outside the town.","had bakers who grew their own wheat."],"answer":2,"explain":"The flour had to come from somewhere, and one local mill was not enough. Growing wheat would not solve the shortage of milling."},{"id":"rw-inf-11","section":"rw","domain":"ii","skill":"inf","level":3,"type":"mc","passage":"Students who were told that a test would be easy studied less and scored lower than students who were told nothing. But students told that the test would be extremely hard also scored lower, reporting that they \"saw no point\" in preparing. Together, the results suggest that motivation to prepare is highest when a task seems ______","question":"Which choice most logically completes the text?","options":["as easy as possible.","impossible to complete.","challenging but achievable.","unrelated to the students' goals."],"answer":2,"explain":"Both \"easy\" and \"extremely hard\" lowered effort, so the best case lies between them."},{"id":"rw-inf-12","section":"rw","domain":"ii","skill":"inf","level":3,"type":"mc","passage":"In a matching test, speakers of a language that uses a single word for both blue and green distinguished the two shades as accurately as English speakers did, yet they were slower to do so. The findings imply that vocabulary ______","question":"Which choice most logically completes the text?","options":["determines which colors a person is able to see.","may affect how quickly distinctions are made without determining whether they can be perceived.","has no connection at all to perception.","is more precise in languages with fewer color words."],"answer":1,"explain":"Same accuracy (so they can see the difference) but lower speed (so words have some effect)."},{"id":"rw-bnd-3","section":"rw","domain":"sec","skill":"bnd","level":1,"type":"mc","passage":"Rabindranath Tagore, who won the Nobel Prize in Literature in ______ wrote the songs that became the national anthems of two countries.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["1913:","1913","1913;","1913,"],"answer":3,"explain":"The \"who\" clause is extra information. It opens with a comma, so it must close with a comma."},{"id":"rw-bnd-4","section":"rw","domain":"sec","skill":"bnd","level":1,"type":"mc","passage":"Engineers testing the new bridge wanted to know how much weight the cables could ______","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["bear:","bear,","bear?","bear."],"answer":3,"explain":"This is a statement that reports a question, so it ends with a full stop, not a question mark."},{"id":"rw-bnd-5","section":"rw","domain":"sec","skill":"bnd","level":1,"type":"mc","passage":"The telescope was completed on ______ clouds prevented astronomers from using it for another month.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["schedule. But,","schedule, but,","schedule but,","schedule, but"],"answer":3,"explain":"Join two complete sentences with a comma before \"but\". No comma follows \"but\"."},{"id":"rw-bnd-8","section":"rw","domain":"sec","skill":"bnd","level":2,"type":"mc","passage":"The astronomer ______ the comet in 1996 named it after her daughter.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["who discovered,",", who discovered",", who, discovered","who discovered"],"answer":3,"explain":"The clause identifies which astronomer, so it is essential and takes no commas."},{"id":"rw-bnd-9","section":"rw","domain":"sec","skill":"bnd","level":2,"type":"mc","passage":"Kazi Nazrul Islam (the national poet of ______ thousands of songs during his career.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["Bangladesh, composed","Bangladesh), composed","Bangladesh; composed","Bangladesh) composed"],"answer":3,"explain":"The bracket that opens must close, and no punctuation separates the subject from its verb \"composed\"."},{"id":"rw-bnd-10","section":"rw","domain":"sec","skill":"bnd","level":2,"type":"mc","passage":"The tall grasses that cover the ______ shelter to dozens of bird species.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["plain; provide","plain, provide","plain: provide","plain provide"],"answer":3,"explain":"Never put punctuation between a subject (\"grasses that cover the plain\") and its verb (\"provide\")."},{"id":"rw-bnd-11","section":"rw","domain":"sec","skill":"bnd","level":2,"type":"mc","passage":"Coral reefs cover less than one percent of the ocean ______ support roughly a quarter of all marine species.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["floor, they","floor yet, they","floor they","floor, yet they"],"answer":3,"explain":"A comma plus \"yet\" correctly joins two complete sentences. A comma alone is a comma splice."},{"id":"rw-bnd-13","section":"rw","domain":"sec","skill":"bnd","level":3,"type":"mc","passage":"The team collected samples from three sites: Sylhet, in the ______ and Khulna, in the southwest.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["northeast, Rajshahi, in the west,","northeast, Rajshahi; in the west;","northeast; Rajshahi, in the west,","northeast; Rajshahi, in the west;"],"answer":3,"explain":"When list items contain commas themselves, semicolons separate the items."},{"id":"rw-bnd-14","section":"rw","domain":"sec","skill":"bnd","level":3,"type":"mc","passage":"The compound (first isolated from a soil sample in ______ now the basis of several antibiotics.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["1948), is","1948; is","1948, is","1948) is"],"answer":3,"explain":"Close the bracket, then continue the main sentence: \"The compound... is now the basis\". No comma splits subject and verb."},{"id":"rw-bnd-15","section":"rw","domain":"sec","skill":"bnd","level":3,"type":"mc","passage":"The committee approved the budget. The mayor, ______ refused to sign it.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["however;","however,","however:","however"],"answer":1,"explain":"Here \"however\" interrupts a single sentence, so it sits between two commas."},{"id":"rw-bnd-16","section":"rw","domain":"sec","skill":"bnd","level":3,"type":"mc","passage":"The sculptor's early pieces were carved from ______ later ones were cast in bronze.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["marble her","marble; her","marble, however her","marble, her"],"answer":1,"explain":"Two complete sentences with no joining word need a semicolon (or a full stop)."},{"id":"rw-fss-3","section":"rw","domain":"sec","skill":"fss","level":1,"type":"mc","passage":"The company announced that ______ would open a new office in Chattogram.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["those","he","it","they"],"answer":2,"explain":"\"Company\" is singular and not a person, so the pronoun is \"it\"."},{"id":"rw-fss-4","section":"rw","domain":"sec","skill":"fss","level":1,"type":"mc","passage":"A single ______ wings can beat up to eighty times per second.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["hummingbird","hummingbirds'","hummingbird's","hummingbirds"],"answer":2,"explain":"One bird owns the wings: singular possessive, apostrophe before the s."},{"id":"rw-fss-5","section":"rw","domain":"sec","skill":"fss","level":1,"type":"mc","passage":"The museum is known for ______ collection of ancient maps.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["its'","their","its","it's"],"answer":2,"explain":"\"Its\" shows possession. \"It's\" means \"it is\", and \"its'\" is never correct."},{"id":"rw-fss-6","section":"rw","domain":"sec","skill":"fss","level":1,"type":"mc","passage":"The students were asked ______ their results before leaving the laboratory.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["to record","record","recorded","recording"],"answer":0,"explain":"\"Asked\" is followed by \"to\" plus a verb: asked to record."},{"id":"rw-fss-9","section":"rw","domain":"sec","skill":"fss","level":2,"type":"mc","passage":"By the time the rescue team arrived, the hikers ______ shelter in a cave.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["had found","have found","will find","find"],"answer":0,"explain":"Finding shelter happened before another past event (the arrival), so use the past perfect."},{"id":"rw-fss-10","section":"rw","domain":"sec","skill":"fss","level":2,"type":"mc","passage":"The internship taught her to analyze data, to write reports, and ______ her findings clearly.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["to present","presentation of","presenting","she presented"],"answer":0,"explain":"Items in a list take the same form: to analyze, to write, to present."},{"id":"rw-fss-11","section":"rw","domain":"sec","skill":"fss","level":2,"type":"mc","passage":"The director thanked Rafiq and ______ for organizing the festival.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["me","mine","I","myself"],"answer":0,"explain":"The pronoun receives the action, so use \"me\". Test it without \"Rafiq and\": \"thanked me\"."},{"id":"rw-fss-12","section":"rw","domain":"sec","skill":"fss","level":2,"type":"mc","passage":"Among the items recovered from the shipwreck ______ a bronze compass and several glass bottles.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["were","has been","was","is"],"answer":0,"explain":"The subject comes after the verb: \"a compass and several bottles\" is plural, so \"were\"."},{"id":"rw-fss-14","section":"rw","domain":"sec","skill":"fss","level":3,"type":"mc","passage":"If the bridge ______ built a decade earlier, the flood would have caused far less disruption.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["has been","was","had been","would have been"],"answer":2,"explain":"For an unreal past condition, use \"had\" plus the past participle in the \"if\" part."},{"id":"rw-fss-15","section":"rw","domain":"sec","skill":"fss","level":3,"type":"mc","passage":"Neither the manager nor the employees ______ aware of the change in schedule.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["has been","was","were","is"],"answer":2,"explain":"With \"neither... nor\", the verb agrees with the nearer subject: \"employees\" is plural."},{"id":"rw-fss-16","section":"rw","domain":"sec","skill":"fss","level":3,"type":"mc","passage":"The rainfall in Sylhet is far greater than ______","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["Rajshahi.","that in Rajshahi.","in Rajshahi is.","Rajshahi's region."],"answer":1,"explain":"Compare like with like: rainfall with rainfall (\"that\"), not rainfall with a city."},{"id":"rw-trn-3","section":"rw","domain":"eoi","skill":"trn","level":1,"type":"mc","passage":"Many animals use tools. ______ sea otters crack open shellfish with stones.","question":"Which choice completes the text with the most logical transition?","options":["However,","For example,","Instead,","As a result,"],"answer":1,"explain":"Sea otters are one case of the general statement before."},{"id":"rw-trn-4","section":"rw","domain":"eoi","skill":"trn","level":1,"type":"mc","passage":"Bamboo grows quickly and needs little water. ______ it can be harvested without killing the plant.","question":"Which choice completes the text with the most logical transition?","options":["Nevertheless,","In addition,","In contrast,","Otherwise,"],"answer":1,"explain":"The second sentence adds one more advantage."},{"id":"rw-trn-7","section":"rw","domain":"eoi","skill":"trn","level":2,"type":"mc","passage":"The star's light takes four years to reach Earth. ______ when we look at it, we see it as it was four years ago.","question":"Which choice completes the text with the most logical transition?","options":["By contrast,","In other words,","However,","For instance,"],"answer":1,"explain":"The second sentence restates the first in a different way."},{"id":"rw-trn-8","section":"rw","domain":"eoi","skill":"trn","level":2,"type":"mc","passage":"Wolves hunt in coordinated packs. ______ orcas work in groups to herd fish into tight clusters.","question":"Which choice completes the text with the most logical transition?","options":["However,","Therefore,","Similarly,","Instead,"],"answer":2,"explain":"Two animals doing a comparable thing: \"Similarly\"."},{"id":"rw-trn-9","section":"rw","domain":"eoi","skill":"trn","level":2,"type":"mc","passage":"The architect did not tear down the old factory. ______ she converted it into apartments, keeping its brick walls and tall windows.","question":"Which choice completes the text with the most logical transition?","options":["Likewise,","For example,","Instead,","Nevertheless,"],"answer":2,"explain":"One action replaced another that did not happen: \"Instead\"."},{"id":"rw-trn-11","section":"rw","domain":"eoi","skill":"trn","level":3,"type":"mc","passage":"Early critics dismissed the painter's work as unfinished. ______ one reviewer suggested that the canvases had been exhibited by mistake.","question":"Which choice completes the text with the most logical transition?","options":["Indeed,","However,","Consequently,","Alternatively,"],"answer":0,"explain":"The second sentence gives a stronger instance of the same point, so \"Indeed\" (in fact) fits."},{"id":"rw-trn-12","section":"rw","domain":"eoi","skill":"trn","level":3,"type":"mc","passage":"Solar panels generate no power at night. ______ when paired with batteries, they can supply a household around the clock.","question":"Which choice completes the text with the most logical transition?","options":["Still,","Thus,","Moreover,","For example,"],"answer":0,"explain":"A limitation is admitted, then a point against it: \"Still\"."},{"id":"rw-syn-3","section":"rw","domain":"eoi","skill":"syn","level":1,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• Begum Rokeya (1880 to 1932) was a Bengali writer and educator.\n• She wrote \"Sultana's Dream\" (1905), a story set in a land governed by women.\n• She ran a school for girls in Kolkata from 1911.\n• She campaigned for women's education.","question":"The student wants to introduce \"Sultana's Dream\" to an audience unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["\"Sultana's Dream,\" a 1905 story by the Bengali writer Begum Rokeya, is set in a land governed by women.","Begum Rokeya, who lived from 1880 to 1932, campaigned for women's education.","Begum Rokeya ran a school for girls in Kolkata from 1911.","A writer and educator, Begum Rokeya produced several works."],"answer":0,"explain":"To introduce the story, say what it is, who wrote it and what it is about."},{"id":"rw-syn-6","section":"rw","domain":"eoi","skill":"syn","level":2,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• The Nile is about 6,650 km long.\n• The Amazon is about 6,400 km long.\n• The Nile flows north to the Mediterranean Sea.\n• The Amazon carries more water than any other river.","question":"The student wants to emphasize a way in which the Amazon exceeds the Nile. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["The Nile flows north to the Mediterranean Sea.","At about 6,650 km, the Nile is longer than the Amazon.","The Amazon is about 6,400 km long.","Though slightly shorter than the Nile, the Amazon carries more water than any other river."],"answer":3,"explain":"The Amazon is ahead in the volume of water it carries, not in length."},{"id":"rw-syn-8","section":"rw","domain":"eoi","skill":"syn","level":3,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• Most honey is made by honeybees of the genus Apis.\n• Stingless bees also make honey.\n• Stingless-bee honey contains more water and tastes more sour.\n• It is produced in much smaller amounts.","question":"The student wants to contrast stingless-bee honey with the honey of Apis bees for readers who know only the latter. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["Stingless bees, like honeybees of the genus Apis, make honey.","Most honey is made by honeybees of the genus Apis, and some is made by stingless bees.","Honey is made by more than one kind of bee.","Compared with the familiar honey of Apis bees, honey from stingless bees contains more water, tastes more sour, and is produced in much smaller amounts."],"answer":3,"explain":"A contrast must state how the two differ: water, taste and quantity."},{"id":"m-lin1-1-3","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"If 7x + 8 = −20, what is the value of x?","options":["−28","−4","−12/7","4"],"answer":1,"explain":"Take 8 from both sides: 7x = −28. Divide by 7: x = −4."},{"id":"m-lin1-1-4","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"If 7x − 9 = 33, what is the value of x?","options":["−6","24/7","6","42"],"answer":2,"explain":"Add 9 to both sides: 7x = 42. Divide by 7: x = 6."},{"id":"m-lin1-1-5","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"If 2x − 8 = −20, what is the value of x?","options":["−14","−12","−6","6"],"answer":2,"explain":"Add 8 to both sides: 2x = −12. Divide by 2: x = −6."},{"id":"m-lin1-1-6","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"If 7x − 10 = 46, what is the value of x?","options":["−8","36/7","8","56"],"answer":2,"explain":"Add 10 to both sides: 7x = 56. Divide by 7: x = 8."},{"id":"m-lin1-2-3","section":"math","domain":"alg","skill":"lin1","level":2,"type":"mc","question":"5(x − 1) = −2x + 16\n\nWhat value of x satisfies the equation above?","options":["−3","11/7","17/7","3"],"answer":3,"explain":"Expand the left side: 5x − 5 = −2x + 16. Collect terms: 7x = 21, so x = 3."},{"id":"m-lin1-2-4","section":"math","domain":"alg","skill":"lin1","level":2,"type":"mc","question":"2(x + 4) = 4x − 10\n\nWhat value of x satisfies the equation above?","options":["−9","1","7","9"],"answer":3,"explain":"Expand the left side: 2x + 8 = 4x − 10. Collect terms: −2x = −18, so x = 9."},{"id":"m-lin1-2-5","section":"math","domain":"alg","skill":"lin1","level":2,"type":"mc","question":"4(x + 3) = x − 15\n\nWhat value of x satisfies the equation above?","options":["−9","−6","−1","9"],"answer":0,"explain":"Expand the left side: 4x + 12 = x − 15. Collect terms: 3x = −27, so x = −9."},{"id":"m-lin1-2-6","section":"math","domain":"alg","skill":"lin1","level":2,"type":"mc","question":"4(x + 1) = 2x + 8\n\nWhat value of x satisfies the equation above?","options":["−2","2","7/2","6"],"answer":1,"explain":"Expand the left side: 4x + 4 = 2x + 8. Collect terms: 2x = 4, so x = 2."},{"id":"m-lin1-3-2","section":"math","domain":"alg","skill":"lin1","level":3,"type":"spr","question":"x/2 + x/3 = 20\n\nWhat value of x satisfies the equation above?","accept":["24"],"values":[24],"explain":"Multiply every term by 6: 3x + 2x = 120, so 5x = 120 and x = 24."},{"id":"m-lin1-3-3","section":"math","domain":"alg","skill":"lin1","level":3,"type":"spr","question":"x/4 + x/6 = 15\n\nWhat value of x satisfies the equation above?","accept":["36"],"values":[36],"explain":"Multiply every term by 12: 3x + 2x = 180, so 5x = 180 and x = 36."},{"id":"m-lin1-3-4","section":"math","domain":"alg","skill":"lin1","level":3,"type":"spr","question":"x/2 + x/3 = 10\n\nWhat value of x satisfies the equation above?","accept":["12"],"values":[12],"explain":"Multiply every term by 6: 3x + 2x = 60, so 5x = 60 and x = 12."},{"id":"m-lin1-3-5","section":"math","domain":"alg","skill":"lin1","level":3,"type":"spr","question":"x/2 + x/3 = 15\n\nWhat value of x satisfies the equation above?","accept":["18"],"values":[18],"explain":"Multiply every term by 6: 3x + 2x = 90, so 5x = 90 and x = 18."},{"id":"m-lin1-3-6","section":"math","domain":"alg","skill":"lin1","level":3,"type":"spr","question":"x/3 + x/4 = 21\n\nWhat value of x satisfies the equation above?","accept":["36"],"values":[36],"explain":"Multiply every term by 12: 4x + 3x = 252, so 7x = 252 and x = 36."},{"id":"m-lin1-1-7","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"A taxi ride costs a fixed fee of $12 plus $2 for each kilometre travelled. A ride cost $20. How many kilometres long was the ride?","options":["4","8","10","16"],"answer":0,"explain":"12 + 2n = 20, so 2n = 8 and n = 4."},{"id":"m-lin1-1-8","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"A bike rental costs $5 plus $4 for each hour. Arif paid $73. For how many hours was the bike rented?","options":["17","73/4","22","68"],"answer":0,"explain":"5 + 4n = 73, so 4n = 68 and n = 17."},{"id":"m-lin1-1-9","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"A bike rental costs $12 plus $3 for each hour. Arif paid $39. For how many hours was the bike rented?","options":["9","13","21","27"],"answer":0,"explain":"12 + 3n = 39, so 3n = 27 and n = 9."},{"id":"m-lin1-1-10","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"A print shop charges a setup fee of $10 plus $3 for each poster. An order cost $37. How many posters were in the order?","options":["9","37/3","19","27"],"answer":0,"explain":"10 + 3n = 37, so 3n = 27 and n = 9."},{"id":"m-lin1-1-11","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"A print shop charges a setup fee of $3 plus $6 for each poster. An order cost $57. How many posters were in the order?","options":["9","19/2","12","54"],"answer":0,"explain":"3 + 6n = 57, so 6n = 54 and n = 9."},{"id":"m-lin1-1-12","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"A print shop charges a setup fee of $10 plus $2 for each poster. An order cost $38. How many posters were in the order?","options":["14","19","24","28"],"answer":0,"explain":"10 + 2n = 38, so 2n = 28 and n = 14."},{"id":"m-lin1-2-7","section":"math","domain":"alg","skill":"lin1","level":2,"type":"spr","question":"Gym A charges a joining fee of $40 plus $5 per week. Gym B charges a joining fee of $58 plus $3 per week. After how many weeks is the total cost of the two gyms the same?","accept":["9"],"values":[9],"explain":"Set the costs equal: 40 + 5w = 58 + 3w. Then 2w = 18, so w = 9."},{"id":"m-lin1-2-8","section":"math","domain":"alg","skill":"lin1","level":2,"type":"spr","question":"Gym A charges a joining fee of $20 plus $7 per week. Gym B charges a joining fee of $38 plus $4 per week. After how many weeks is the total cost of the two gyms the same?","accept":["6"],"values":[6],"explain":"Set the costs equal: 20 + 7w = 38 + 4w. Then 3w = 18, so w = 6."},{"id":"m-lin1-2-9","section":"math","domain":"alg","skill":"lin1","level":2,"type":"spr","question":"Gym A charges a joining fee of $40 plus $10 per week. Gym B charges a joining fee of $55 plus $5 per week. After how many weeks is the total cost of the two gyms the same?","accept":["3"],"values":[3],"explain":"Set the costs equal: 40 + 10w = 55 + 5w. Then 5w = 15, so w = 3."},{"id":"m-lin1-2-10","section":"math","domain":"alg","skill":"lin1","level":2,"type":"spr","question":"Gym A charges a joining fee of $40 plus $7 per week. Gym B charges a joining fee of $64 plus $3 per week. After how many weeks is the total cost of the two gyms the same?","accept":["6"],"values":[6],"explain":"Set the costs equal: 40 + 7w = 64 + 3w. Then 4w = 24, so w = 6."},{"id":"m-lin1-2-11","section":"math","domain":"alg","skill":"lin1","level":2,"type":"spr","question":"Gym A charges a joining fee of $10 plus $5 per week. Gym B charges a joining fee of $32 plus $3 per week. After how many weeks is the total cost of the two gyms the same?","accept":["11"],"values":[11],"explain":"Set the costs equal: 10 + 5w = 32 + 3w. Then 2w = 22, so w = 11."},{"id":"m-lin1-2-12","section":"math","domain":"alg","skill":"lin1","level":2,"type":"spr","question":"Gym A charges a joining fee of $10 plus $7 per week. Gym B charges a joining fee of $46 plus $4 per week. After how many weeks is the total cost of the two gyms the same?","accept":["12"],"values":[12],"explain":"Set the costs equal: 10 + 7w = 46 + 4w. Then 3w = 36, so w = 12."},{"id":"m-lin1-3-7","section":"math","domain":"alg","skill":"lin1","level":3,"type":"mc","question":"4(x + 3) = kx + 10\n\nIn the equation above, k is a constant. The equation has no solution. What is the value of k?","options":["4","7","10","12"],"answer":0,"explain":"The left side is 4x + 12. With k = 4 the x-terms match but the constants (12 and 10) do not, so no value of x works."},{"id":"m-lin1-3-8","section":"math","domain":"alg","skill":"lin1","level":3,"type":"mc","question":"5(x + 2) = kx + 13\n\nIn the equation above, k is a constant. The equation has no solution. What is the value of k?","options":["5","7","10","13"],"answer":0,"explain":"The left side is 5x + 10. With k = 5 the x-terms match but the constants (10 and 13) do not, so no value of x works."},{"id":"m-lin1-3-9","section":"math","domain":"alg","skill":"lin1","level":3,"type":"mc","question":"5(x + 2) = kx + 5\n\nIn the equation above, k is a constant. The equation has no solution. What is the value of k?","options":["5","6","7","10"],"answer":0,"explain":"The left side is 5x + 10. With k = 5 the x-terms match but the constants (10 and 5) do not, so no value of x works."},{"id":"m-lin1-3-10","section":"math","domain":"alg","skill":"lin1","level":3,"type":"mc","question":"2(x + 7) = 2x + c\n\nIn the equation above, c is a constant. The equation has infinitely many solutions. What is the value of c?","options":["2","7","9","14"],"answer":3,"explain":"The left side is 2x + 14. Both sides are the same for every x only when c = 14."},{"id":"m-lin1-3-11","section":"math","domain":"alg","skill":"lin1","level":3,"type":"mc","question":"5(x + 4) = 5x + c\n\nIn the equation above, c is a constant. The equation has infinitely many solutions. What is the value of c?","options":["4","5","9","20"],"answer":3,"explain":"The left side is 5x + 20. Both sides are the same for every x only when c = 20."},{"id":"m-lin1-3-12","section":"math","domain":"alg","skill":"lin1","level":3,"type":"mc","question":"6(x + 7) = kx + 44\n\nIn the equation above, k is a constant. The equation has no solution. What is the value of k?","options":["6","13","42","44"],"answer":0,"explain":"The left side is 6x + 42. With k = 6 the x-terms match but the constants (42 and 44) do not, so no value of x works."},{"id":"m-lin2-1-3","section":"math","domain":"alg","skill":"lin2","level":1,"type":"mc","question":"In the xy-plane, a line passes through the points (0, 6) and (1, 8). What is the slope of the line?","options":["−2","−1/2","1/2","2"],"answer":3,"explain":"Slope = change in y over change in x = (8 − 6) / (1 − 0) = 2/1 = 2."},{"id":"m-lin2-1-4","section":"math","domain":"alg","skill":"lin2","level":1,"type":"mc","question":"In the xy-plane, a line passes through the points (−1, 4) and (1, −4). What is the slope of the line?","options":["−4","−1/4","1/4","4"],"answer":0,"explain":"Slope = change in y over change in x = (−4 − 4) / (1 − (−1)) = −8/2 = −4."},{"id":"m-lin2-1-5","section":"math","domain":"alg","skill":"lin2","level":1,"type":"mc","question":"In the xy-plane, a line passes through the points (−2, −3) and (1, 2). What is the slope of the line?","options":["−5/3","−3/5","3/5","5/3"],"answer":3,"explain":"Slope = change in y over change in x = (2 − (−3)) / (1 − (−2)) = 5/3."},{"id":"m-lin2-1-6","section":"math","domain":"alg","skill":"lin2","level":1,"type":"mc","question":"In the xy-plane, a line passes through the points (−4, −2) and (−1, 6). What is the slope of the line?","options":["−8/3","−3/8","3/8","8/3"],"answer":3,"explain":"Slope = change in y over change in x = (6 − (−2)) / (−1 − (−4)) = 8/3."},{"id":"m-lin2-2-3","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"A line in the xy-plane has a slope of 4 and passes through the point (−3, 2). Which equation represents the line?","options":["y = 4x + 14","y = 4x − 10","y = 4x + 2","y = 14x + 4"],"answer":0,"explain":"Use y = mx + b with m = 4: 2 = 4(−3) + b, so b = 14."},{"id":"m-lin2-2-4","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"A line in the xy-plane has a slope of 4 and passes through the point (2, −4). Which equation represents the line?","options":["y = 4x − 12","y = −12x + 4","y = 4x + 4","y = 4x − 4"],"answer":0,"explain":"Use y = mx + b with m = 4: −4 = 4(2) + b, so b = −12."},{"id":"m-lin2-2-5","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"A line in the xy-plane has a slope of 2 and passes through the point (2, −1). Which equation represents the line?","options":["y = 2x − 1","y = −5x + 2","y = 2x + 3","y = 2x − 5"],"answer":3,"explain":"Use y = mx + b with m = 2: −1 = 2(2) + b, so b = −5."},{"id":"m-lin2-2-6","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"A line in the xy-plane has a slope of 3 and passes through the point (3, 5). Which equation represents the line?","options":["y = 3x + 5","y = 3x − 4","y = −4x + 3","y = 3x + 14"],"answer":1,"explain":"Use y = mx + b with m = 3: 5 = 3(3) + b, so b = −4."},{"id":"m-lin2-1-7","section":"math","domain":"alg","skill":"lin2","level":1,"type":"spr","question":"The graph of 3x + 4y = 27 in the xy-plane crosses the x-axis at the point (k, 0). What is the value of k?","accept":["9"],"values":[9],"explain":"On the x-axis y = 0, so 3x = 27 and x = 9."},{"id":"m-lin2-1-8","section":"math","domain":"alg","skill":"lin2","level":1,"type":"spr","question":"The graph of 3x + 7y = 27 in the xy-plane crosses the x-axis at the point (k, 0). What is the value of k?","accept":["9"],"values":[9],"explain":"On the x-axis y = 0, so 3x = 27 and x = 9."},{"id":"m-lin2-1-9","section":"math","domain":"alg","skill":"lin2","level":1,"type":"spr","question":"The graph of 2x + 5y = 14 in the xy-plane crosses the x-axis at the point (k, 0). What is the value of k?","accept":["7"],"values":[7],"explain":"On the x-axis y = 0, so 2x = 14 and x = 7."},{"id":"m-lin2-1-10","section":"math","domain":"alg","skill":"lin2","level":1,"type":"spr","question":"The graph of 2x + 7y = 12 in the xy-plane crosses the x-axis at the point (k, 0). What is the value of k?","accept":["6"],"values":[6],"explain":"On the x-axis y = 0, so 2x = 12 and x = 6."},{"id":"m-lin2-1-11","section":"math","domain":"alg","skill":"lin2","level":1,"type":"spr","question":"The graph of 3x + 7y = 12 in the xy-plane crosses the x-axis at the point (k, 0). What is the value of k?","accept":["4"],"values":[4],"explain":"On the x-axis y = 0, so 3x = 12 and x = 4."},{"id":"m-lin2-1-12","section":"math","domain":"alg","skill":"lin2","level":1,"type":"spr","question":"The graph of 4x + 2y = 20 in the xy-plane crosses the x-axis at the point (k, 0). What is the value of k?","accept":["5"],"values":[5],"explain":"On the x-axis y = 0, so 4x = 20 and x = 5."},{"id":"m-lin2-2-7","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"In the xy-plane, the graph of 3x − 7y = 42 crosses the y-axis at (0, k). What is the value of k?","options":["−14","−6","6","14"],"answer":1,"explain":"On the y-axis x = 0, so −7y = 42 and y = −6."},{"id":"m-lin2-2-8","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"In the xy-plane, the graph of 2x − 3y = 6 crosses the y-axis at (0, k). What is the value of k?","options":["−3","−2","2","3"],"answer":1,"explain":"On the y-axis x = 0, so −3y = 6 and y = −2."},{"id":"m-lin2-2-9","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"In the xy-plane, the graph of 3x − 5y = 30 crosses the y-axis at (0, k). What is the value of k?","options":["−10","−6","6","10"],"answer":1,"explain":"On the y-axis x = 0, so −5y = 30 and y = −6."},{"id":"m-lin2-2-10","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"In the xy-plane, the graph of 6x − 2y = 12 crosses the y-axis at (0, k). What is the value of k?","options":["−6","−2","2","6"],"answer":0,"explain":"On the y-axis x = 0, so −2y = 12 and y = −6."},{"id":"m-lin2-2-11","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"In the xy-plane, the graph of 6x − 4y = 24 crosses the y-axis at (0, k). What is the value of k?","options":["−6","−4","4","6"],"answer":0,"explain":"On the y-axis x = 0, so −4y = 24 and y = −6."},{"id":"m-lin2-2-12","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"In the xy-plane, the graph of 6x − 4y = 48 crosses the y-axis at (0, k). What is the value of k?","options":["−12","−8","8","12"],"answer":0,"explain":"On the y-axis x = 0, so −4y = 48 and y = −12."},{"id":"m-lin2-3-2","section":"math","domain":"alg","skill":"lin2","level":3,"type":"mc","question":"Line k is defined by 2x + 5y = 3. Line j is parallel to line k in the xy-plane. What is the slope of line j?","options":["−2/5","5/2","−5/2","2/5"],"answer":0,"explain":"Solve for y: y = (−2/5)x + 3/5, so line k has slope −2/5. Parallel lines have equal slopes."},{"id":"m-lin2-3-3","section":"math","domain":"alg","skill":"lin2","level":3,"type":"mc","question":"Line k is defined by 2x + 3y = 4. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","options":["−2/3","−3/2","2/3","3/2"],"answer":3,"explain":"Solve for y: y = (−2/3)x + 4/3, so line k has slope −2/3. A perpendicular line has the negative reciprocal slope: 3/2."},{"id":"m-lin2-3-4","section":"math","domain":"alg","skill":"lin2","level":3,"type":"mc","question":"Line k is defined by 2x + 5y = 4. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","options":["−5/2","2/5","−2/5","5/2"],"answer":3,"explain":"Solve for y: y = (−2/5)x + 4/5, so line k has slope −2/5. A perpendicular line has the negative reciprocal slope: 5/2."},{"id":"m-lin2-3-5","section":"math","domain":"alg","skill":"lin2","level":3,"type":"mc","question":"Line k is defined by 3x + 2y = 6. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","options":["2/3","−2/3","3/2","−3/2"],"answer":0,"explain":"Solve for y: y = (−3/2)x + 3, so line k has slope −3/2. A perpendicular line has the negative reciprocal slope: 2/3."},{"id":"m-lin2-3-6","section":"math","domain":"alg","skill":"lin2","level":3,"type":"mc","question":"Line k is defined by 3x + 5y = 11. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","options":["3/5","−3/5","5/3","−5/3"],"answer":2,"explain":"Solve for y: y = (−3/5)x + 11/5, so line k has slope −3/5. A perpendicular line has the negative reciprocal slope: 5/3."},{"id":"m-linf-1-3","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function f is defined by f(x) = −2x + 4. What is the value of f(6)?","options":["−16","−12","−8","8"],"answer":2,"explain":"f(6) = −2(6) + 4 = −12 + 4 = −8."},{"id":"m-linf-1-4","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function f is defined by f(x) = 3x − 1. What is the value of f(2)?","options":["4","5","6","7"],"answer":1,"explain":"f(2) = 3(2) − 1 = 6 − 1 = 5."},{"id":"m-linf-1-5","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function f is defined by f(x) = −3x + 12. What is the value of f(6)?","options":["−30","−18","−6","15"],"answer":2,"explain":"f(6) = −3(6) + 12 = −18 + 12 = −6."},{"id":"m-linf-1-6","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function f is defined by f(x) = −4x + 1. What is the value of f(−2)?","options":["−5","7","8","9"],"answer":3,"explain":"f(−2) = −4(−2) + 1 = 8 + 1 = 9."},{"id":"m-linf-2-3","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"For the linear function f, f(1) = 2 and f(5) = 22. What is the value of f(10)?","options":["24","27","47","52"],"answer":2,"explain":"The slope is (22 − 2) / (5 − 1) = 5. From x = 5 to x = 10 the function changes by 5 × 5 = 25, giving 47."},{"id":"m-linf-2-4","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"For the linear function f, f(3) = 17 and f(7) = 25. What is the value of f(10)?","options":["28","31","33","42"],"answer":1,"explain":"The slope is (25 − 17) / (7 − 3) = 2. From x = 7 to x = 10 the function changes by 2 × 3 = 6, giving 31."},{"id":"m-linf-2-5","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"For the linear function f, f(0) = 11 and f(4) = 27. What is the value of f(7)?","options":["30","38","39","43"],"answer":2,"explain":"The slope is (27 − 11) / (4 − 0) = 4. From x = 4 to x = 7 the function changes by 4 × 3 = 12, giving 39."},{"id":"m-linf-2-6","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"For the linear function f, f(2) = 15 and f(4) = 19. What is the value of f(9)?","options":["24","29","31","34"],"answer":1,"explain":"The slope is (19 − 15) / (4 − 2) = 2. From x = 4 to x = 9 the function changes by 2 × 5 = 10, giving 29."},{"id":"m-linf-3-2","section":"math","domain":"alg","skill":"linf","level":3,"type":"spr","question":"For the linear function g, g(3) = 5 and g(5) = 9. The graph of y = g(x) in the xy-plane crosses the y-axis at (0, b). What is the value of b?","accept":["-1"],"values":[-1],"explain":"The slope is 2. Using g(3) = 5: 5 = 2(3) + b, so b = −1."},{"id":"m-linf-3-3","section":"math","domain":"alg","skill":"linf","level":3,"type":"spr","question":"For the linear function g, g(1) = 9 and g(3) = 19. The graph of y = g(x) in the xy-plane crosses the y-axis at (0, b). What is the value of b?","accept":["4"],"values":[4],"explain":"The slope is 5. Using g(1) = 9: 9 = 5(1) + b, so b = 4."},{"id":"m-linf-3-4","section":"math","domain":"alg","skill":"linf","level":3,"type":"spr","question":"For the linear function g, g(3) = −5 and g(7) = −17. The graph of y = g(x) in the xy-plane crosses the y-axis at (0, b). What is the value of b?","accept":["4"],"values":[4],"explain":"The slope is −3. Using g(3) = −5: −5 = −3(3) + b, so b = 4."},{"id":"m-linf-3-5","section":"math","domain":"alg","skill":"linf","level":3,"type":"spr","question":"For the linear function g, g(3) = 8 and g(6) = 20. The graph of y = g(x) in the xy-plane crosses the y-axis at (0, b). What is the value of b?","accept":["-4"],"values":[-4],"explain":"The slope is 4. Using g(3) = 8: 8 = 4(3) + b, so b = −4."},{"id":"m-linf-3-6","section":"math","domain":"alg","skill":"linf","level":3,"type":"spr","question":"For the linear function g, g(3) = −8 and g(5) = −12. The graph of y = g(x) in the xy-plane crosses the y-axis at (0, b). What is the value of b?","accept":["-2"],"values":[-2],"explain":"The slope is −2. Using g(3) = −8: −8 = −2(3) + b, so b = −2."},{"id":"m-linf-1-7","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function C(t) = 15t + 20 gives the total cost, in dollars, of hiring a van for t hours. What is the best interpretation of 20 in this context?","options":["The number of hours in the booking","The charge for each additional hour","The total cost for 20 hours","The fixed charge, before any hours are added"],"answer":3,"explain":"When t = 0, C(0) = 20. It is the part of the cost that does not depend on time."},{"id":"m-linf-1-8","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function C(t) = 18t + 40 gives the total cost, in dollars, of hiring a van for t hours. What is the best interpretation of 40 in this context?","options":["The fixed charge, before any hours are added","The charge for each additional hour","The number of hours in the booking","The total cost for 40 hours"],"answer":0,"explain":"When t = 0, C(0) = 40. It is the part of the cost that does not depend on time."},{"id":"m-linf-1-9","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function C(t) = 15t + 40 gives the total cost, in dollars, of hiring a van for t hours. What is the best interpretation of 40 in this context?","options":["The number of hours in the booking","The charge for each additional hour","The fixed charge, before any hours are added","The total cost for 40 hours"],"answer":2,"explain":"When t = 0, C(0) = 40. It is the part of the cost that does not depend on time."},{"id":"m-linf-1-10","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function C(t) = 8t + 50 gives the total cost, in dollars, of renting a boat for t hours. What is the best interpretation of 50 in this context?","options":["The fixed charge, before any hours are added","The charge for each additional hour","The number of hours in the booking","The total cost for 50 hours"],"answer":0,"explain":"When t = 0, C(0) = 50. It is the part of the cost that does not depend on time."},{"id":"m-linf-1-11","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function C(t) = 18t + 75 gives the total cost, in dollars, of renting a boat for t hours. What is the best interpretation of 75 in this context?","options":["The fixed charge, before any hours are added","The total cost for 75 hours","The number of hours in the booking","The charge for each additional hour"],"answer":0,"explain":"When t = 0, C(0) = 75. It is the part of the cost that does not depend on time."},{"id":"m-linf-1-12","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function C(t) = 8t + 40 gives the total cost, in dollars, of booking a hall for t hours. What is the best interpretation of 40 in this context?","options":["The fixed charge, before any hours are added","The charge for each additional hour","The number of hours in the booking","The total cost for 40 hours"],"answer":0,"explain":"When t = 0, C(0) = 40. It is the part of the cost that does not depend on time."},{"id":"m-linf-2-7","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"A water tank is being emptied. The function W(m) = 60 − 6m gives the number of litres of water left in the tank m minutes after emptying begins. What is the best interpretation of 6 in this context?","options":["The number of litres left after 6 minutes","The number of litres that leave the tank each minute","The number of litres in the tank when emptying begins","The number of minutes it takes to empty the tank"],"answer":1,"explain":"Each time m goes up by 1, W(m) goes down by 6. So 6 is the rate, in litres per minute, at which water leaves."},{"id":"m-linf-2-8","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"A water tank is being emptied. The function W(m) = 120 − 12m gives the number of litres of water left in the tank m minutes after emptying begins. What is the best interpretation of 12 in this context?","options":["The number of litres in the tank when emptying begins","The number of litres left after 12 minutes","The number of litres that leave the tank each minute","The number of minutes it takes to empty the tank"],"answer":2,"explain":"Each time m goes up by 1, W(m) goes down by 12. So 12 is the rate, in litres per minute, at which water leaves."},{"id":"m-linf-2-9","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"A water tank is being emptied. The function W(m) = 80 − 8m gives the number of litres of water left in the tank m minutes after emptying begins. What is the best interpretation of 8 in this context?","options":["The number of minutes it takes to empty the tank","The number of litres left after 8 minutes","The number of litres that leave the tank each minute","The number of litres in the tank when emptying begins"],"answer":2,"explain":"Each time m goes up by 1, W(m) goes down by 8. So 8 is the rate, in litres per minute, at which water leaves."},{"id":"m-linf-2-10","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"A water tank is being emptied. The function W(m) = 144 − 12m gives the number of litres of water left in the tank m minutes after emptying begins. What is the best interpretation of 12 in this context?","options":["The number of litres left after 12 minutes","The number of minutes it takes to empty the tank","The number of litres in the tank when emptying begins","The number of litres that leave the tank each minute"],"answer":3,"explain":"Each time m goes up by 1, W(m) goes down by 12. So 12 is the rate, in litres per minute, at which water leaves."},{"id":"m-linf-2-11","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"A water tank is being emptied. The function W(m) = 180 − 15m gives the number of litres of water left in the tank m minutes after emptying begins. What is the best interpretation of 15 in this context?","options":["The number of minutes it takes to empty the tank","The number of litres that leave the tank each minute","The number of litres left after 15 minutes","The number of litres in the tank when emptying begins"],"answer":1,"explain":"Each time m goes up by 1, W(m) goes down by 15. So 15 is the rate, in litres per minute, at which water leaves."},{"id":"m-linf-2-12","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"A water tank is being emptied. The function W(m) = 180 − 18m gives the number of litres of water left in the tank m minutes after emptying begins. What is the best interpretation of 18 in this context?","options":["The number of litres left after 18 minutes","The number of litres in the tank when emptying begins","The number of litres that leave the tank each minute","The number of minutes it takes to empty the tank"],"answer":2,"explain":"Each time m goes up by 1, W(m) goes down by 18. So 18 is the rate, in litres per minute, at which water leaves."},{"id":"m-sys-1-3","section":"math","domain":"alg","skill":"sys","level":1,"type":"mc","question":"x + y = 1\nx − y = 7\n\nThe solution to the system above is (x, y). What is the value of x?","options":["−3","1","4","7"],"answer":2,"explain":"Add the equations: 2x = 8, so x = 4."},{"id":"m-sys-1-4","section":"math","domain":"alg","skill":"sys","level":1,"type":"mc","question":"x + y = 5\nx − y = 13\n\nThe solution to the system above is (x, y). What is the value of x?","options":["−4","5","9","13"],"answer":2,"explain":"Add the equations: 2x = 18, so x = 9."},{"id":"m-sys-1-5","section":"math","domain":"alg","skill":"sys","level":1,"type":"mc","question":"x + y = 15\nx − y = 3\n\nThe solution to the system above is (x, y). What is the value of x?","options":["3","6","9","15"],"answer":2,"explain":"Add the equations: 2x = 18, so x = 9."},{"id":"m-sys-1-6","section":"math","domain":"alg","skill":"sys","level":1,"type":"mc","question":"x + y = 7\nx − y = 3\n\nThe solution to the system above is (x, y). What is the value of x?","options":["2","3","5","7"],"answer":2,"explain":"Add the equations: 2x = 10, so x = 5."},{"id":"m-sys-2-3","section":"math","domain":"alg","skill":"sys","level":2,"type":"mc","question":"3x − y = −2\n2x + y = −8\n\nIf (x, y) is the solution to the system above, what is the value of x + y?","options":["−6","−4","−2","2"],"answer":0,"explain":"Solving the system gives x = −2 and y = −4, so x + y = −6."},{"id":"m-sys-2-4","section":"math","domain":"alg","skill":"sys","level":2,"type":"mc","question":"2x + y = 2\nx − y = −11\n\nIf (x, y) is the solution to the system above, what is the value of x + y?","options":["−11","−3","5","8"],"answer":2,"explain":"Solving the system gives x = −3 and y = 8, so x + y = 5."},{"id":"m-sys-2-5","section":"math","domain":"alg","skill":"sys","level":2,"type":"mc","question":"2x + 3y = 33\nx − 2y = −8\n\nIf (x, y) is the solution to the system above, what is the value of x + y?","options":["−1","6","7","13"],"answer":3,"explain":"Solving the system gives x = 6 and y = 7, so x + y = 13."},{"id":"m-sys-2-6","section":"math","domain":"alg","skill":"sys","level":2,"type":"mc","question":"4x + y = 27\n3x − y = 22\n\nIf (x, y) is the solution to the system above, what is the value of x + y?","options":["−1","6","7","8"],"answer":1,"explain":"Solving the system gives x = 7 and y = −1, so x + y = 6."},{"id":"m-sys-2-7","section":"math","domain":"alg","skill":"sys","level":2,"type":"spr","question":"A school play sold 149 tickets. Adult tickets cost $15 each and student tickets cost $4 each. Ticket sales came to $1,333. How many adult tickets were sold?","accept":["67"],"values":[67],"explain":"Let a and s be the numbers of adult and student tickets: a + s = 149 and 15a + 4s = 1333. Substitute s = 149 − a: 11a = 737, so a = 67."},{"id":"m-sys-2-8","section":"math","domain":"alg","skill":"sys","level":2,"type":"spr","question":"A school play sold 87 tickets. Adult tickets cost $12 each and student tickets cost $3 each. Ticket sales came to $486. How many adult tickets were sold?","accept":["25"],"values":[25],"explain":"Let a and s be the numbers of adult and student tickets: a + s = 87 and 12a + 3s = 486. Substitute s = 87 − a: 9a = 225, so a = 25."},{"id":"m-sys-2-9","section":"math","domain":"alg","skill":"sys","level":2,"type":"spr","question":"A school play sold 94 tickets. Adult tickets cost $15 each and student tickets cost $4 each. Ticket sales came to $761. How many adult tickets were sold?","accept":["35"],"values":[35],"explain":"Let a and s be the numbers of adult and student tickets: a + s = 94 and 15a + 4s = 761. Substitute s = 94 − a: 11a = 385, so a = 35."},{"id":"m-sys-2-10","section":"math","domain":"alg","skill":"sys","level":2,"type":"spr","question":"A school play sold 124 tickets. Adult tickets cost $12 each and student tickets cost $4 each. Ticket sales came to $928. How many adult tickets were sold?","accept":["54"],"values":[54],"explain":"Let a and s be the numbers of adult and student tickets: a + s = 124 and 12a + 4s = 928. Substitute s = 124 − a: 8a = 432, so a = 54."},{"id":"m-sys-2-11","section":"math","domain":"alg","skill":"sys","level":2,"type":"spr","question":"A school play sold 97 tickets. Adult tickets cost $10 each and student tickets cost $3 each. Ticket sales came to $501. How many adult tickets were sold?","accept":["30"],"values":[30],"explain":"Let a and s be the numbers of adult and student tickets: a + s = 97 and 10a + 3s = 501. Substitute s = 97 − a: 7a = 210, so a = 30."},{"id":"m-sys-2-12","section":"math","domain":"alg","skill":"sys","level":2,"type":"spr","question":"A school play sold 101 tickets. Adult tickets cost $15 each and student tickets cost $6 each. Ticket sales came to $1,092. How many adult tickets were sold?","accept":["54"],"values":[54],"explain":"Let a and s be the numbers of adult and student tickets: a + s = 101 and 15a + 6s = 1092. Substitute s = 101 − a: 9a = 486, so a = 54."},{"id":"m-sys-3-2","section":"math","domain":"alg","skill":"sys","level":3,"type":"mc","question":"4x + 5y = 10\nkx + 20y = 38\n\nIn the system above, k is a constant. The system has no solution. What is the value of k?","options":["1","4","16","20"],"answer":2,"explain":"No solution means the lines are parallel: the left sides are multiples of each other but the right sides are not. 20y is 4 times 5y, so k = 4 × 4 = 16 (and 38 is not 4 × 10)."},{"id":"m-sys-3-3","section":"math","domain":"alg","skill":"sys","level":3,"type":"mc","question":"5x + 7y = 12\nkx + 14y = 20\n\nIn the system above, k is a constant. The system has no solution. What is the value of k?","options":["5/2","5","10","14"],"answer":2,"explain":"No solution means the lines are parallel: the left sides are multiples of each other but the right sides are not. 14y is 2 times 7y, so k = 2 × 5 = 10 (and 20 is not 2 × 12)."},{"id":"m-sys-3-4","section":"math","domain":"alg","skill":"sys","level":3,"type":"mc","question":"4x + 2y = 3\nkx + 4y = 2\n\nIn the system above, k is a constant. The system has no solution. What is the value of k?","options":["2","4","8","9"],"answer":2,"explain":"No solution means the lines are parallel: the left sides are multiples of each other but the right sides are not. 4y is 2 times 2y, so k = 2 × 4 = 8 (and 2 is not 2 × 3)."},{"id":"m-sys-3-5","section":"math","domain":"alg","skill":"sys","level":3,"type":"mc","question":"5x + 2y = 3\nkx + 4y = 11\n\nIn the system above, k is a constant. The system has no solution. What is the value of k?","options":["5/2","4","5","10"],"answer":3,"explain":"No solution means the lines are parallel: the left sides are multiples of each other but the right sides are not. 4y is 2 times 2y, so k = 2 × 5 = 10 (and 11 is not 2 × 3)."},{"id":"m-sys-3-6","section":"math","domain":"alg","skill":"sys","level":3,"type":"mc","question":"2x + 5y = 4\nkx + 10y = 6\n\nIn the system above, k is a constant. The system has no solution. What is the value of k?","options":["1","2","4","10"],"answer":2,"explain":"No solution means the lines are parallel: the left sides are multiples of each other but the right sides are not. 10y is 2 times 5y, so k = 2 × 2 = 4 (and 6 is not 2 × 4)."},{"id":"m-ineq-1-3","section":"math","domain":"alg","skill":"ineq","level":1,"type":"mc","question":"Which of the following describes all solutions to 3x − 1 > 14?","options":["x > 5","x > −5","x < 5","x < −5"],"answer":0,"explain":"Add 1 to both sides: 3x > 15. Divide by 3: x > 5."},{"id":"m-ineq-1-4","section":"math","domain":"alg","skill":"ineq","level":1,"type":"mc","question":"Which of the following describes all solutions to 2x − 9 > −5?","options":["x < −2","x > 2","x > −2","x < 2"],"answer":1,"explain":"Add 9 to both sides: 2x > 4. Divide by 2: x > 2."},{"id":"m-ineq-1-5","section":"math","domain":"alg","skill":"ineq","level":1,"type":"mc","question":"Which of the following describes all solutions to 5x − 6 > −21?","options":["x < −3","x > 3","x < 3","x > −3"],"answer":3,"explain":"Add 6 to both sides: 5x > −15. Divide by 5: x > −3."},{"id":"m-ineq-1-6","section":"math","domain":"alg","skill":"ineq","level":1,"type":"mc","question":"Which of the following describes all solutions to 5x − 6 > −1?","options":["x > −1","x < 1","x < −1","x > 1"],"answer":3,"explain":"Add 6 to both sides: 5x > 5. Divide by 5: x > 1."},{"id":"m-ineq-2-3","section":"math","domain":"alg","skill":"ineq","level":2,"type":"mc","question":"Which of the following describes all solutions to −6x + 4 > −14?","options":["x < 3","x > −3","x > 3","x < −3"],"answer":0,"explain":"Take 4 from both sides: −6x > −18. Dividing by a negative number reverses the sign: x < 3."},{"id":"m-ineq-2-4","section":"math","domain":"alg","skill":"ineq","level":2,"type":"mc","question":"Which of the following describes all solutions to −4x + 5 > −27?","options":["x > −8","x > 8","x < 8","x < −8"],"answer":2,"explain":"Take 5 from both sides: −4x > −32. Dividing by a negative number reverses the sign: x < 8."},{"id":"m-ineq-2-5","section":"math","domain":"alg","skill":"ineq","level":2,"type":"mc","question":"Which of the following describes all solutions to −6x + 9 > −15?","options":["x < −4","x > −4","x > 4","x < 4"],"answer":3,"explain":"Take 9 from both sides: −6x > −24. Dividing by a negative number reverses the sign: x < 4."},{"id":"m-ineq-2-6","section":"math","domain":"alg","skill":"ineq","level":2,"type":"mc","question":"Which of the following describes all solutions to −4x + 2 > 14?","options":["x < −3","x < 3","x > 3","x > −3"],"answer":0,"explain":"Take 2 from both sides: −4x > 12. Dividing by a negative number reverses the sign: x < −3."},{"id":"m-ineq-2-7","section":"math","domain":"alg","skill":"ineq","level":2,"type":"spr","question":"Tania has $90 to spend on concert tickets. Each ticket costs $7, and there is a single booking fee of $15 for the whole order. What is the greatest number of tickets Tania can buy?","accept":["10"],"values":[10],"explain":"7t + 15 ≤ 90, so 7t ≤ 75 and t ≤ 10.71. The number of tickets must be whole, so the most is 10."},{"id":"m-ineq-2-8","section":"math","domain":"alg","skill":"ineq","level":2,"type":"spr","question":"Maya has $60 to spend on concert tickets. Each ticket costs $14, and there is a single booking fee of $15 for the whole order. What is the greatest number of tickets Maya can buy?","accept":["3"],"values":[3],"explain":"14t + 15 ≤ 60, so 14t ≤ 45 and t ≤ 3.21. The number of tickets must be whole, so the most is 3."},{"id":"m-ineq-2-9","section":"math","domain":"alg","skill":"ineq","level":2,"type":"spr","question":"Sami has $150 to spend on concert tickets. Each ticket costs $12, and there is a single booking fee of $15 for the whole order. What is the greatest number of tickets Sami can buy?","accept":["11"],"values":[11],"explain":"12t + 15 ≤ 150, so 12t ≤ 135 and t ≤ 11.25. The number of tickets must be whole, so the most is 11."},{"id":"m-ineq-2-10","section":"math","domain":"alg","skill":"ineq","level":2,"type":"spr","question":"Arif has $120 to spend on concert tickets. Each ticket costs $9, and there is a single booking fee of $5 for the whole order. What is the greatest number of tickets Arif can buy?","accept":["12"],"values":[12],"explain":"9t + 5 ≤ 120, so 9t ≤ 115 and t ≤ 12.78. The number of tickets must be whole, so the most is 12."},{"id":"m-ineq-2-11","section":"math","domain":"alg","skill":"ineq","level":2,"type":"spr","question":"Rafi has $120 to spend on concert tickets. Each ticket costs $12, and there is a single booking fee of $15 for the whole order. What is the greatest number of tickets Rafi can buy?","accept":["8"],"values":[8],"explain":"12t + 15 ≤ 120, so 12t ≤ 105 and t ≤ 8.75. The number of tickets must be whole, so the most is 8."},{"id":"m-ineq-2-12","section":"math","domain":"alg","skill":"ineq","level":2,"type":"spr","question":"Tania has $60 to spend on concert tickets. Each ticket costs $12, and there is a single booking fee of $15 for the whole order. What is the greatest number of tickets Tania can buy?","accept":["3"],"values":[3],"explain":"12t + 15 ≤ 60, so 12t ≤ 45 and t ≤ 3.75. The number of tickets must be whole, so the most is 3."},{"id":"m-ineq-3-2","section":"math","domain":"alg","skill":"ineq","level":3,"type":"mc","question":"y > 3x\ny ≤ −2x + 6\n\nWhich point (x, y) is a solution to the system of inequalities above?","options":["(−3, 5)","(2, 6)","(4, 1)","(1, −3)"],"answer":0,"explain":"Test each point in both inequalities. For (−3, 5): 5 > −9 and 5 ≤ 12, so both hold. Each other point fails at least one."},{"id":"m-ineq-3-3","section":"math","domain":"alg","skill":"ineq","level":3,"type":"mc","question":"y > x + 2\ny ≤ −2x + 6\n\nWhich point (x, y) is a solution to the system of inequalities above?","options":["(−2, −3)","(−2, −1)","(−2, 8)","(1, 1)"],"answer":2,"explain":"Test each point in both inequalities. For (−2, 8): 8 > 0 and 8 ≤ 10, so both hold. Each other point fails at least one."},{"id":"m-ineq-3-4","section":"math","domain":"alg","skill":"ineq","level":3,"type":"mc","question":"y > 3x − 3\ny ≤ −x + 5\n\nWhich point (x, y) is a solution to the system of inequalities above?","options":["(1, 8)","(−3, 8)","(3, 4)","(2, 3)"],"answer":1,"explain":"Test each point in both inequalities. For (−3, 8): 8 > −12 and 8 ≤ 8, so both hold. Each other point fails at least one."},{"id":"m-ineq-3-5","section":"math","domain":"alg","skill":"ineq","level":3,"type":"mc","question":"y > x − 3\ny ≤ −x + 7\n\nWhich point (x, y) is a solution to the system of inequalities above?","options":["(4, 7)","(1, 8)","(0, 2)","(3, 6)"],"answer":2,"explain":"Test each point in both inequalities. For (0, 2): 2 > −3 and 2 ≤ 7, so both hold. Each other point fails at least one."},{"id":"m-ineq-3-6","section":"math","domain":"alg","skill":"ineq","level":3,"type":"mc","question":"y > x − 1\ny ≤ −x + 5\n\nWhich point (x, y) is a solution to the system of inequalities above?","options":["(3, −1)","(−2, −3)","(−2, 0)","(1, 6)"],"answer":2,"explain":"Test each point in both inequalities. For (−2, 0): 0 > −3 and 0 ≤ 7, so both hold. Each other point fails at least one."},{"id":"m-eqx-1-3","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (x − 7)(x + 6)?","options":["x² − 42x − 1","x² − x − 42","x² − x − 1","x² − 42"],"answer":1,"explain":"Multiply each term: x² + 6x − 7x − 42 = x² − x − 42."},{"id":"m-eqx-1-4","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (x − 6)(x + 7)?","options":["x² − 42x + 1","x² + x + 1","x² − 42","x² + x − 42"],"answer":3,"explain":"Multiply each term: x² + 7x − 6x − 42 = x² + x − 42."},{"id":"m-eqx-1-5","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (x + 5)(x − 6)?","options":["x² − x − 30","x² − 30x − 1","x² − 30","x² − x − 1"],"answer":0,"explain":"Multiply each term: x² − 6x + 5x − 30 = x² − x − 30."},{"id":"m-eqx-1-6","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (x + 3)(x − 4)?","options":["x² − 12x − 1","x² − x − 1","x² − 12","x² − x − 12"],"answer":3,"explain":"Multiply each term: x² − 4x + 3x − 12 = x² − x − 12."},{"id":"m-eqx-2-3","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"Which expression is equivalent to x² + 4x − 32?","options":["(x − 4)(x + 8)","(x − 32)(x + 1)","(x + 4)(x − 8)","(x − 4)(x − 8)"],"answer":0,"explain":"Find two numbers that multiply to −32 and add to 4: −4 and 8. So the expression is (x − 4)(x + 8)."},{"id":"m-eqx-2-4","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"Which expression is equivalent to x² + 2x − 8?","options":["(x − 8)(x + 1)","(x − 2)(x − 4)","(x + 2)(x − 4)","(x − 2)(x + 4)"],"answer":3,"explain":"Find two numbers that multiply to −8 and add to 2: −2 and 4. So the expression is (x − 2)(x + 4)."},{"id":"m-eqx-2-5","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"Which expression is equivalent to x² + x − 12?","options":["(x − 3)(x − 4)","(x + 3)(x − 4)","(x − 3)(x + 4)","(x − 12)(x + 1)"],"answer":2,"explain":"Find two numbers that multiply to −12 and add to 1: −3 and 4. So the expression is (x − 3)(x + 4)."},{"id":"m-eqx-2-6","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"Which expression is equivalent to x² + 11x + 30?","options":["(x + 6)(x − 5)","(x + 6)(x + 5)","(x + 30)(x + 1)","(x − 6)(x − 5)"],"answer":1,"explain":"Find two numbers that multiply to 30 and add to 11: 6 and 5. So the expression is (x + 6)(x + 5)."},{"id":"m-eqx-1-7","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (3x²)(3x³)?","options":["9x⁶","9x⁵","6x⁵","6x⁶"],"answer":1,"explain":"Multiply the numbers (3 × 3 = 9) and add the exponents (2 + 3 = 5)."},{"id":"m-eqx-1-8","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (2x⁴)(6x⁶)?","options":["8x²⁴","12x²⁴","8x¹⁰","12x¹⁰"],"answer":3,"explain":"Multiply the numbers (2 × 6 = 12) and add the exponents (4 + 6 = 10)."},{"id":"m-eqx-1-9","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (3x⁵)(3x²)?","options":["9x¹⁰","6x¹⁰","6x⁷","9x⁷"],"answer":3,"explain":"Multiply the numbers (3 × 3 = 9) and add the exponents (5 + 2 = 7)."},{"id":"m-eqx-1-10","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (2x³)(3x⁶)?","options":["5x⁹","6x⁹","5x¹⁸","6x¹⁸"],"answer":1,"explain":"Multiply the numbers (2 × 3 = 6) and add the exponents (3 + 6 = 9)."},{"id":"m-eqx-1-11","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (5x³)(2x²)?","options":["7x⁶","10x⁵","7x⁵","10x⁶"],"answer":1,"explain":"Multiply the numbers (5 × 2 = 10) and add the exponents (3 + 2 = 5)."},{"id":"m-eqx-1-12","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (5x²)(6x³)?","options":["30x⁶","11x⁶","11x⁵","30x⁵"],"answer":3,"explain":"Multiply the numbers (5 × 6 = 30) and add the exponents (2 + 3 = 5)."},{"id":"m-eqx-2-7","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 0, which expression is equivalent to (x³)⁶ / x²?","options":["x¹⁶","x⁷","x¹⁸","x²⁰"],"answer":0,"explain":"A power of a power multiplies the exponents: x¹⁸. Dividing subtracts: 18 − 2 = 16."},{"id":"m-eqx-2-8","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 0, which expression is equivalent to (x³)⁶ / x³?","options":["x¹⁵","x²¹","x⁶","x¹⁸"],"answer":0,"explain":"A power of a power multiplies the exponents: x¹⁸. Dividing subtracts: 18 − 3 = 15."},{"id":"m-eqx-2-9","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 0, which expression is equivalent to (x²)⁴ / x²?","options":["x¹⁰","x⁸","x⁶","x⁴"],"answer":2,"explain":"A power of a power multiplies the exponents: x⁸. Dividing subtracts: 8 − 2 = 6."},{"id":"m-eqx-2-10","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 0, which expression is equivalent to (x³)² / x?","options":["x⁵","x⁷","x⁴","x⁶"],"answer":0,"explain":"A power of a power multiplies the exponents: x⁶. Dividing subtracts: 6 − 1 = 5."},{"id":"m-eqx-2-11","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 0, which expression is equivalent to (x²)⁶ / x?","options":["x¹³","x¹²","x¹¹","x⁷"],"answer":2,"explain":"A power of a power multiplies the exponents: x¹². Dividing subtracts: 12 − 1 = 11."},{"id":"m-eqx-2-12","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 0, which expression is equivalent to (x⁴)⁶ / x³?","options":["x²⁷","x²⁴","x²¹","x⁷"],"answer":2,"explain":"A power of a power multiplies the exponents: x²⁴. Dividing subtracts: 24 − 3 = 21."},{"id":"m-eqx-2-13","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 6, which expression is equivalent to (x² − 36) / (x − 6)?","options":["x² − 6","x − 6","x + 36","x + 6"],"answer":3,"explain":"x² − 36 is a difference of squares: (x − 6)(x + 6). The factor (x − 6) cancels, leaving x + 6."},{"id":"m-eqx-2-14","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 8, which expression is equivalent to (x² − 64) / (x − 8)?","options":["x − 8","x + 8","x² − 8","x + 64"],"answer":1,"explain":"x² − 64 is a difference of squares: (x − 8)(x + 8). The factor (x − 8) cancels, leaving x + 8."},{"id":"m-eqx-2-15","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 5, which expression is equivalent to (x² − 25) / (x − 5)?","options":["x + 5","x² − 5","x − 5","x + 25"],"answer":0,"explain":"x² − 25 is a difference of squares: (x − 5)(x + 5). The factor (x − 5) cancels, leaving x + 5."},{"id":"m-eqx-2-16","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 9, which expression is equivalent to (x² − 81) / (x − 9)?","options":["x + 81","x − 9","x² − 9","x + 9"],"answer":3,"explain":"x² − 81 is a difference of squares: (x − 9)(x + 9). The factor (x − 9) cancels, leaving x + 9."},{"id":"m-eqx-2-17","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 2, which expression is equivalent to (x² − 4) / (x − 2)?","options":["x − 2","x + 4","x² − 2","x + 2"],"answer":3,"explain":"x² − 4 is a difference of squares: (x − 2)(x + 2). The factor (x − 2) cancels, leaving x + 2."},{"id":"m-eqx-2-18","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"For x ≠ 3, which expression is equivalent to (x² − 9) / (x − 3)?","options":["x − 3","x + 3","x + 9","x² − 3"],"answer":1,"explain":"x² − 9 is a difference of squares: (x − 3)(x + 3). The factor (x − 3) cancels, leaving x + 3."},{"id":"m-eqx-3-2","section":"math","domain":"adv","skill":"eqx","level":3,"type":"mc","question":"Which expression is equivalent to (4x + 3)² − (4x − 3)²?","options":["48x","18","32x² + 18","0"],"answer":0,"explain":"Expand both squares: (16x² + 24x + 9) − (16x² − 24x + 9). The x² terms and the constants cancel, leaving 48x."},{"id":"m-eqx-3-3","section":"math","domain":"adv","skill":"eqx","level":3,"type":"mc","question":"For x > 0, which of the following is equivalent to x^(3/2)?","options":["The square root of x³","x³ divided by 2","The cube root of x²","x³ minus x²"],"answer":0,"explain":"In a fractional exponent the top number is the power and the bottom number is the root: x^(3/2) is the square root of x³."},{"id":"m-eqx-3-4","section":"math","domain":"adv","skill":"eqx","level":3,"type":"mc","question":"Which expression is equivalent to (x + 5)² − (x − 5)²?","options":["20x","50","0","2x² + 50"],"answer":0,"explain":"Expand both squares: (x² + 10x + 25) − (x² − 10x + 25). The x² terms and the constants cancel, leaving 20x."},{"id":"m-eqx-3-5","section":"math","domain":"adv","skill":"eqx","level":3,"type":"mc","question":"For x > 0, which of the following is equivalent to x^(2/3)?","options":["x² divided by 3","The cube root of x²","x² minus x³","The square root of x³"],"answer":1,"explain":"In a fractional exponent the top number is the power and the bottom number is the root: x^(2/3) is the cube root of x²."},{"id":"m-eqx-3-6","section":"math","domain":"adv","skill":"eqx","level":3,"type":"mc","question":"Which expression is equivalent to (2x + 3)² − (2x − 3)²?","options":["18","24x","8x² + 18","0"],"answer":1,"explain":"Expand both squares: (4x² + 12x + 9) − (4x² − 12x + 9). The x² terms and the constants cancel, leaving 24x."},{"id":"m-nleq-1-3","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"x² − 5x − 36 = 0\n\nWhat is the positive solution to the equation above?","accept":["9"],"values":[9],"explain":"Factor: (x − 9)(x + 4) = 0, so x = 9 or x = −4. The positive solution is 9."},{"id":"m-nleq-1-4","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"x² + x − 30 = 0\n\nWhat is the positive solution to the equation above?","accept":["5"],"values":[5],"explain":"Factor: (x − 5)(x + 6) = 0, so x = 5 or x = −6. The positive solution is 5."},{"id":"m-nleq-1-5","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"x² − 4x − 5 = 0\n\nWhat is the positive solution to the equation above?","accept":["5"],"values":[5],"explain":"Factor: (x − 5)(x + 1) = 0, so x = 5 or x = −1. The positive solution is 5."},{"id":"m-nleq-1-6","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"x² − 4x − 32 = 0\n\nWhat is the positive solution to the equation above?","accept":["8"],"values":[8],"explain":"Factor: (x − 8)(x + 4) = 0, so x = 8 or x = −4. The positive solution is 8."},{"id":"m-nleq-2-3","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to 2x² + 7x − 1 = 0?","options":["7/2","−7/2","−1/2","1/2"],"answer":1,"explain":"For ax² + bx + c = 0 the solutions add up to −b/a = −7/2. (Here b² − 4ac is positive, so there are two real solutions.)"},{"id":"m-nleq-2-4","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to 2x² − 9x − 3 = 0?","options":["−3/2","9/2","−9/2","3/2"],"answer":1,"explain":"For ax² + bx + c = 0 the solutions add up to −b/a = 9/2. (Here b² − 4ac is positive, so there are two real solutions.)"},{"id":"m-nleq-2-5","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to 4x² + 6x − 1 = 0?","options":["−1/4","−3/2","1/4","3/2"],"answer":1,"explain":"For ax² + bx + c = 0 the solutions add up to −b/a = −3/2. (Here b² − 4ac is positive, so there are two real solutions.)"},{"id":"m-nleq-2-6","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to 3x² + x − 5 = 0?","options":["−5/3","1/3","5/3","−1/3"],"answer":3,"explain":"For ax² + bx + c = 0 the solutions add up to −b/a = −1/3. (Here b² − 4ac is positive, so there are two real solutions.)"},{"id":"m-nleq-2-7","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"How many distinct real solutions does the equation 3x² − x + 7 = 0 have?","options":["Exactly one","Infinitely many","Exactly two","Zero"],"answer":3,"explain":"The discriminant is b² − 4ac = 1 − 84 = −83. It is negative, so there are no real solutions."},{"id":"m-nleq-2-8","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"How many distinct real solutions does the equation 2x² − 4x + 8 = 0 have?","options":["Infinitely many","Zero","Exactly two","Exactly one"],"answer":1,"explain":"The discriminant is b² − 4ac = 16 − 64 = −48. It is negative, so there are no real solutions."},{"id":"m-nleq-2-9","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"How many distinct real solutions does the equation 3x² − 7x + 5 = 0 have?","options":["Infinitely many","Exactly one","Zero","Exactly two"],"answer":2,"explain":"The discriminant is b² − 4ac = 49 − 60 = −11. It is negative, so there are no real solutions."},{"id":"m-nleq-2-10","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"How many distinct real solutions does the equation x² + 9 = 0 have?","options":["Exactly two","Exactly one","Zero","Infinitely many"],"answer":2,"explain":"The discriminant is b² − 4ac = 0 − 36 = −36. It is negative, so there are no real solutions."},{"id":"m-nleq-2-11","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"How many distinct real solutions does the equation 2x² + 6x + 3 = 0 have?","options":["Zero","Exactly two","Exactly one","Infinitely many"],"answer":1,"explain":"The discriminant is b² − 4ac = 36 − 24 = 12. It is positive, so there are two real solutions."},{"id":"m-nleq-2-12","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"How many distinct real solutions does the equation 3x² + 4x + 4 = 0 have?","options":["Exactly one","Exactly two","Zero","Infinitely many"],"answer":2,"explain":"The discriminant is b² − 4ac = 16 − 48 = −32. It is negative, so there are no real solutions."},{"id":"m-nleq-3-2","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"x² − 8x + c = 0\n\nIn the equation above, c is a constant. The equation has exactly one real solution. What is the value of c?","accept":["16"],"values":[16],"explain":"One real solution means the discriminant is zero: (8)² − 4c = 0, so 4c = 64 and c = 16."},{"id":"m-nleq-3-3","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"x² − 18x + c = 0\n\nIn the equation above, c is a constant. The equation has exactly one real solution. What is the value of c?","accept":["81"],"values":[81],"explain":"One real solution means the discriminant is zero: (18)² − 4c = 0, so 4c = 324 and c = 81."},{"id":"m-nleq-3-4","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"x² − 4x + c = 0\n\nIn the equation above, c is a constant. The equation has exactly one real solution. What is the value of c?","accept":["4"],"values":[4],"explain":"One real solution means the discriminant is zero: (4)² − 4c = 0, so 4c = 16 and c = 4."},{"id":"m-nleq-3-5","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"x² − 14x + c = 0\n\nIn the equation above, c is a constant. The equation has exactly one real solution. What is the value of c?","accept":["49"],"values":[49],"explain":"One real solution means the discriminant is zero: (14)² − 4c = 0, so 4c = 196 and c = 49."},{"id":"m-nleq-3-6","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"x² − 6x + c = 0\n\nIn the equation above, c is a constant. The equation has exactly one real solution. What is the value of c?","accept":["9"],"values":[9],"explain":"One real solution means the discriminant is zero: (6)² − 4c = 0, so 4c = 36 and c = 9."},{"id":"m-nleq-2-13","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to |x + 4| = 7?","options":["−11","−8","3","14"],"answer":1,"explain":"x + 4 = 7 gives x = 3; x + 4 = −7 gives x = −11. Their sum is −8."},{"id":"m-nleq-2-14","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the smaller of the two solutions to |x − 8| = 4?","options":["−12","−4","4","12"],"answer":2,"explain":"x − 8 = 4 gives x = 12; x − 8 = −4 gives x = 4. The smaller one is 4."},{"id":"m-nleq-2-15","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to |x + 3| = 9?","options":["−12","−6","6","18"],"answer":1,"explain":"x + 3 = 9 gives x = 6; x + 3 = −9 gives x = −12. Their sum is −6."},{"id":"m-nleq-2-16","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to |x − 3| = 7?","options":["−4","6","10","14"],"answer":1,"explain":"x − 3 = 7 gives x = 10; x − 3 = −7 gives x = −4. Their sum is 6."},{"id":"m-nleq-2-17","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to |x + 3| = 7?","options":["−10","−6","4","14"],"answer":1,"explain":"x + 3 = 7 gives x = 4; x + 3 = −7 gives x = −10. Their sum is −6."},{"id":"m-nleq-2-18","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to |x − 4| = 8?","options":["−4","8","12","16"],"answer":1,"explain":"x − 4 = 8 gives x = 12; x − 4 = −8 gives x = −4. Their sum is 8."},{"id":"m-nleq-1-7","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"√(x − 7) = 8\n\nWhat value of x satisfies the equation above?","accept":["71"],"values":[71],"explain":"Square both sides: x − 7 = 64, so x = 71."},{"id":"m-nleq-1-8","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"√(x + 11) = 3\n\nWhat value of x satisfies the equation above?","accept":["-2"],"values":[-2],"explain":"Square both sides: x + 11 = 9, so x = −2."},{"id":"m-nleq-1-9","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"√(x + 10) = 7\n\nWhat value of x satisfies the equation above?","accept":["39"],"values":[39],"explain":"Square both sides: x + 10 = 49, so x = 39."},{"id":"m-nleq-1-10","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"√(x + 8) = 9\n\nWhat value of x satisfies the equation above?","accept":["73"],"values":[73],"explain":"Square both sides: x + 8 = 81, so x = 73."},{"id":"m-nleq-1-11","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"√(x + 8) = 5\n\nWhat value of x satisfies the equation above?","accept":["17"],"values":[17],"explain":"Square both sides: x + 8 = 25, so x = 17."},{"id":"m-nleq-1-12","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"√(x − 6) = 7\n\nWhat value of x satisfies the equation above?","accept":["55"],"values":[55],"explain":"Square both sides: x − 6 = 49, so x = 55."},{"id":"m-nleq-3-7","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"y = x²\ny = x + 20\n\nThe graphs of the two equations above cross at two points in the xy-plane. What is the x-coordinate of the point of intersection for which x > 0?","accept":["5"],"values":[5],"explain":"Set them equal: x² = x + 20, so x² − x − 20 = 0, which factors as (x − 5)(x + 4) = 0. The positive solution is x = 5."},{"id":"m-nleq-3-8","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"y = x²\ny = 5x + 6\n\nThe graphs of the two equations above cross at two points in the xy-plane. What is the x-coordinate of the point of intersection for which x > 0?","accept":["6"],"values":[6],"explain":"Set them equal: x² = 5x + 6, so x² − 5x − 6 = 0, which factors as (x − 6)(x + 1) = 0. The positive solution is x = 6."},{"id":"m-nleq-3-9","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"y = x²\ny = 3x + 28\n\nThe graphs of the two equations above cross at two points in the xy-plane. What is the x-coordinate of the point of intersection for which x > 0?","accept":["7"],"values":[7],"explain":"Set them equal: x² = 3x + 28, so x² − 3x − 28 = 0, which factors as (x − 7)(x + 4) = 0. The positive solution is x = 7."},{"id":"m-nleq-3-10","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"y = x²\ny = x + 2\n\nThe graphs of the two equations above cross at two points in the xy-plane. What is the x-coordinate of the point of intersection for which x > 0?","accept":["2"],"values":[2],"explain":"Set them equal: x² = x + 2, so x² − x − 2 = 0, which factors as (x − 2)(x + 1) = 0. The positive solution is x = 2."},{"id":"m-nleq-3-11","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"y = x²\ny = 3x + 10\n\nThe graphs of the two equations above cross at two points in the xy-plane. What is the x-coordinate of the point of intersection for which x > 0?","accept":["5"],"values":[5],"explain":"Set them equal: x² = 3x + 10, so x² − 3x − 10 = 0, which factors as (x − 5)(x + 2) = 0. The positive solution is x = 5."},{"id":"m-nleq-3-12","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"y = x²\ny = 4x + 5\n\nThe graphs of the two equations above cross at two points in the xy-plane. What is the x-coordinate of the point of intersection for which x > 0?","accept":["5"],"values":[5],"explain":"Set them equal: x² = 4x + 5, so x² − 4x − 5 = 0, which factors as (x − 5)(x + 1) = 0. The positive solution is x = 5."},{"id":"m-nlf-1-3","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function f is defined by f(x) = x² + 3x + 8. What is the value of f(−3)?","options":["−10","−7","8","26"],"answer":2,"explain":"f(−3) = 1(9) − 9 + 8 = 8. Remember that (−3)² = 9."},{"id":"m-nlf-1-4","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function f is defined by f(x) = 2x² + 4x + 2. What is the value of f(4)?","options":["−14","18","34","50"],"answer":3,"explain":"f(4) = 2(16) + 16 + 2 = 50. Remember that (4)² = 16."},{"id":"m-nlf-1-5","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function f is defined by f(x) = 3x² − 5x − 8. What is the value of f(−3)?","options":["−20","−11","4","34"],"answer":3,"explain":"f(−3) = 3(9) + 15 − 8 = 34. Remember that (−3)² = 9."},{"id":"m-nlf-1-6","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function f is defined by f(x) = 3x² + 4x − 2. What is the value of f(−3)?","options":["−41","−32","13","37"],"answer":2,"explain":"f(−3) = 3(9) − 12 − 2 = 13. Remember that (−3)² = 9."},{"id":"m-nlf-2-3","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function f is defined by f(x) = 2(x − 3)² − 8. What is the minimum value of f?","options":["−8","−3","3","8"],"answer":0,"explain":"A square is never negative, so (x − 3)² is smallest (zero) when x = 3. The minimum value is then −8."},{"id":"m-nlf-2-4","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function g is defined by g(x) = −2(x − 5)² + 9. For what value of x does g(x) reach its maximum?","options":["−9","−5","5","9"],"answer":2,"explain":"The squared term is zero when x = 5, and for every other x it makes g smaller. So the maximum is at x = 5."},{"id":"m-nlf-2-5","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function g is defined by g(x) = −3(x + 6)² + 2. For what value of x does g(x) reach its maximum?","options":["−6","−2","2","6"],"answer":0,"explain":"The squared term is zero when x = −6, and for every other x it makes g smaller. So the maximum is at x = −6."},{"id":"m-nlf-2-6","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function g is defined by g(x) = −(x − 1)² − 9. For what value of x does g(x) reach its maximum?","options":["−9","−1","1","9"],"answer":2,"explain":"The squared term is zero when x = 1, and for every other x it makes g smaller. So the maximum is at x = 1."},{"id":"m-nlf-3-2","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"The function f is defined by f(x) = x² − 4x + 2. What is the minimum value of f?","options":["−2","−1","2","6"],"answer":0,"explain":"Complete the square: f(x) = (x − 2)² − 2. The minimum is −2, at x = 2."},{"id":"m-nlf-3-3","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"The function f is defined by f(x) = x² + 8x + 6. What is the minimum value of f?","options":["−10","−4","6","22"],"answer":0,"explain":"Complete the square: f(x) = (x + 4)² − 10. The minimum is −10, at x = −4."},{"id":"m-nlf-3-4","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"The function f is defined by f(x) = x² + 10x + 2. What is the minimum value of f?","options":["−23","−5","2","27"],"answer":0,"explain":"Complete the square: f(x) = (x + 5)² − 23. The minimum is −23, at x = −5."},{"id":"m-nlf-3-5","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"The function f is defined by f(x) = x² + 4x + 8. What is the minimum value of f?","options":["−2","4","8","12"],"answer":1,"explain":"Complete the square: f(x) = (x + 2)² + 4. The minimum is 4, at x = −2."},{"id":"m-nlf-3-6","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"The function f is defined by f(x) = x² − 10x + 3. What is the minimum value of f?","options":["−22","3","5","28"],"answer":0,"explain":"Complete the square: f(x) = (x − 5)² − 22. The minimum is −22, at x = 5."},{"id":"m-nlf-1-7","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function P is defined by P(t) = 10(3)ᵗ. What is the value of P(4)?","options":["91","120","810","900"],"answer":2,"explain":"P(4) = 10 × 3⁴ = 10 × 81 = 810."},{"id":"m-nlf-1-8","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function P is defined by P(t) = 3(2)ᵗ. What is the value of P(4)?","options":["19","24","36","48"],"answer":3,"explain":"P(4) = 3 × 2⁴ = 3 × 16 = 48."},{"id":"m-nlf-1-9","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function P is defined by P(t) = 3(3)ᵗ. What is the value of P(3)?","options":["27","30","81","82"],"answer":2,"explain":"P(3) = 3 × 3³ = 3 × 27 = 81."},{"id":"m-nlf-1-10","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function P is defined by P(t) = 5(3)ᵗ. What is the value of P(2)?","options":["14","17","30","45"],"answer":3,"explain":"P(2) = 5 × 3² = 5 × 9 = 45."},{"id":"m-nlf-1-11","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function P is defined by P(t) = 20(3)ᵗ. What is the value of P(3)?","options":["47","180","540","3600"],"answer":2,"explain":"P(3) = 20 × 3³ = 20 × 27 = 540."},{"id":"m-nlf-1-12","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function P is defined by P(t) = 10(3)ᵗ. What is the value of P(3)?","options":["37","90","270","900"],"answer":2,"explain":"P(3) = 10 × 3³ = 10 × 27 = 270."},{"id":"m-nlf-2-7","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function V(t) = 800(1.08)ᵗ gives the value, in dollars, of an investment t years after it was made. Which statement is the best interpretation of 1.08?","options":["The value grows by $8 each year.","The value grows by 1.08% each year.","The value grows by 108% each year.","The value grows by 8% each year."],"answer":3,"explain":"Multiplying by 1.08 each year means keeping 100% and adding 8%."},{"id":"m-nlf-2-8","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function V(t) = 1,200(1.08)ᵗ gives the value, in dollars, of an investment t years after it was made. Which statement is the best interpretation of 1.08?","options":["The value grows by 8% each year.","The value grows by 108% each year.","The value grows by 1.08% each year.","The value grows by $8 each year."],"answer":0,"explain":"Multiplying by 1.08 each year means keeping 100% and adding 8%."},{"id":"m-nlf-2-9","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function V(t) = 500(1.02)ᵗ gives the value, in dollars, of an investment t years after it was made. Which statement is the best interpretation of 1.02?","options":["The value grows by 1.02% each year.","The value grows by 102% each year.","The value grows by 2% each year.","The value grows by $2 each year."],"answer":2,"explain":"Multiplying by 1.02 each year means keeping 100% and adding 2%."},{"id":"m-nlf-2-10","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function M(t) = 2,000(0.92)ᵗ gives the mass, in grams, of a substance t days after an experiment begins. Which statement is the best interpretation of 0.92?","options":["The mass falls by 8% each day.","The mass falls by 0.92 grams each day.","The mass falls by 92% each day.","The mass falls by 8 grams each day."],"answer":0,"explain":"Multiplying by 0.92 each day keeps 92% of the mass, so 8% is lost."},{"id":"m-nlf-2-11","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function V(t) = 500(1.04)ᵗ gives the value, in dollars, of an investment t years after it was made. Which statement is the best interpretation of 1.04?","options":["The value grows by 1.04% each year.","The value grows by 4% each year.","The value grows by 104% each year.","The value grows by $4 each year."],"answer":1,"explain":"Multiplying by 1.04 each year means keeping 100% and adding 4%."},{"id":"m-nlf-2-12","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function M(t) = 500(0.97)ᵗ gives the mass, in grams, of a substance t days after an experiment begins. Which statement is the best interpretation of 0.97?","options":["The mass falls by 3% each day.","The mass falls by 3 grams each day.","The mass falls by 0.97 grams each day.","The mass falls by 97% each day."],"answer":0,"explain":"Multiplying by 0.97 each day keeps 97% of the mass, so 3% is lost."},{"id":"m-nlf-3-7","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"A colony of 300 bacteria doubles every 4 hours. Which function gives the number of bacteria, N(t), in the colony t hours after it is first counted?","options":["N(t) = 300(4)^(2t)","N(t) = 300(2)^(4t)","N(t) = 300(2)^(t/4)","N(t) = 300 + 8t"],"answer":2,"explain":"The colony is multiplied by 2 once for every 4 hours, which is t/4 times in t hours."},{"id":"m-nlf-3-8","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"A colony of 200 bacteria triples every 4 hours. Which function gives the number of bacteria, N(t), in the colony t hours after it is first counted?","options":["N(t) = 200(3)^(t/4)","N(t) = 200(4)^(3t)","N(t) = 200 + 12t","N(t) = 200(3)^(4t)"],"answer":0,"explain":"The colony is multiplied by 3 once for every 4 hours, which is t/4 times in t hours."},{"id":"m-nlf-3-9","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"A colony of 500 bacteria doubles every 4 hours. Which function gives the number of bacteria, N(t), in the colony t hours after it is first counted?","options":["N(t) = 500 + 8t","N(t) = 500(4)^(2t)","N(t) = 500(2)^(4t)","N(t) = 500(2)^(t/4)"],"answer":3,"explain":"The colony is multiplied by 2 once for every 4 hours, which is t/4 times in t hours."},{"id":"m-nlf-3-10","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"A colony of 1,500 bacteria triples every 5 hours. Which function gives the number of bacteria, N(t), in the colony t hours after it is first counted?","options":["N(t) = 1,500(3)^(5t)","N(t) = 1,500(3)^(t/5)","N(t) = 1,500(5)^(3t)","N(t) = 1,500 + 15t"],"answer":1,"explain":"The colony is multiplied by 3 once for every 5 hours, which is t/5 times in t hours."},{"id":"m-nlf-3-11","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"A colony of 500 bacteria doubles every 6 hours. Which function gives the number of bacteria, N(t), in the colony t hours after it is first counted?","options":["N(t) = 500 + 12t","N(t) = 500(2)^(6t)","N(t) = 500(6)^(2t)","N(t) = 500(2)^(t/6)"],"answer":3,"explain":"The colony is multiplied by 2 once for every 6 hours, which is t/6 times in t hours."},{"id":"m-nlf-3-12","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"A colony of 500 bacteria doubles every 5 hours. Which function gives the number of bacteria, N(t), in the colony t hours after it is first counted?","options":["N(t) = 500(2)^(t/5)","N(t) = 500 + 10t","N(t) = 500(5)^(2t)","N(t) = 500(2)^(5t)"],"answer":0,"explain":"The colony is multiplied by 2 once for every 5 hours, which is t/5 times in t hours."},{"id":"m-rate-1-3","section":"math","domain":"psda","skill":"rate","level":1,"type":"mc","question":"A train travels 90 kilometres in 2 hours at a constant speed. At this speed, how many kilometres does it travel in 5 hours?","options":["95","135","225","450"],"answer":2,"explain":"Speed = 90 / 2 = 45 km per hour. In 5 hours: 45 × 5 = 225 km."},{"id":"m-rate-1-4","section":"math","domain":"psda","skill":"rate","level":1,"type":"mc","question":"A recipe uses 2 cups of rice to serve 4 people. At this rate, how many cups of rice are needed to serve 12 people?","options":["5","6","8","10"],"answer":1,"explain":"12 people is 3 times 4 people, so use 3 × 2 = 6 cups."},{"id":"m-rate-1-5","section":"math","domain":"psda","skill":"rate","level":1,"type":"mc","question":"A train travels 80 kilometres in 2 hours at a constant speed. At this speed, how many kilometres does it travel in 6 hours?","options":["86","160","240","480"],"answer":2,"explain":"Speed = 80 / 2 = 40 km per hour. In 6 hours: 40 × 6 = 240 km."},{"id":"m-rate-1-6","section":"math","domain":"psda","skill":"rate","level":1,"type":"mc","question":"A recipe uses 4 cups of rice to serve 6 people. At this rate, how many cups of rice are needed to serve 42 people?","options":["11","24","28","38"],"answer":2,"explain":"42 people is 7 times 6 people, so use 7 × 4 = 28 cups."},{"id":"m-rate-2-3","section":"math","domain":"psda","skill":"rate","level":2,"type":"mc","question":"A car travels at a constant speed of 36 kilometres per hour. What is its speed in metres per second? (1 kilometre = 1,000 metres)","options":["3/5","10","648/5","600"],"answer":1,"explain":"36 km per hour = 36,000 metres per 3,600 seconds = 10 metres per second."},{"id":"m-rate-2-4","section":"math","domain":"psda","skill":"rate","level":2,"type":"mc","question":"A printer prints 12 pages per minute. How many hours does it take to print 540 pages?","options":["1/5","3/4","9","45"],"answer":1,"explain":"540 / 12 = 45 minutes, and 45 minutes is 3/4 hours."},{"id":"m-rate-2-5","section":"math","domain":"psda","skill":"rate","level":2,"type":"mc","question":"A printer prints 18 pages per minute. How many hours does it take to print 810 pages?","options":["3/10","3/4","27/2","45"],"answer":1,"explain":"810 / 18 = 45 minutes, and 45 minutes is 3/4 hours."},{"id":"m-rate-2-6","section":"math","domain":"psda","skill":"rate","level":2,"type":"mc","question":"A car travels at a constant speed of 18 kilometres per hour. What is its speed in metres per second? (1 kilometre = 1,000 metres)","options":["3/10","5","324/5","300"],"answer":1,"explain":"18 km per hour = 18,000 metres per 3,600 seconds = 5 metres per second."},{"id":"m-rate-3-2","section":"math","domain":"psda","skill":"rate","level":3,"type":"mc","question":"A car uses 6 litres of fuel for every 100 kilometres. Fuel costs $1.75 per litre. What is the cost of the fuel for a 350-kilometre trip?","options":["$6.125","$21","$36.75","$73.5"],"answer":2,"explain":"Fuel used: 350 / 100 × 6 = 21 litres. Cost: 21 × $1.75 = $36.75."},{"id":"m-rate-3-3","section":"math","domain":"psda","skill":"rate","level":3,"type":"mc","question":"A car uses 5 litres of fuel for every 100 kilometres. Fuel costs $2.00 per litre. What is the cost of the fuel for a 250-kilometre trip?","options":["$5","$12.5","$25","$50"],"answer":2,"explain":"Fuel used: 250 / 100 × 5 = 12.5 litres. Cost: 12.5 × $2.00 = $25.00."},{"id":"m-rate-3-4","section":"math","domain":"psda","skill":"rate","level":3,"type":"mc","question":"A car uses 8 litres of fuel for every 100 kilometres. Fuel costs $1.25 per litre. What is the cost of the fuel for a 250-kilometre trip?","options":["$3.125","$20","$25","$50"],"answer":2,"explain":"Fuel used: 250 / 100 × 8 = 20 litres. Cost: 20 × $1.25 = $25.00."},{"id":"m-rate-3-5","section":"math","domain":"psda","skill":"rate","level":3,"type":"mc","question":"A car uses 6 litres of fuel for every 100 kilometres. Fuel costs $2.00 per litre. What is the cost of the fuel for a 600-kilometre trip?","options":["$12","$36","$72","$144"],"answer":2,"explain":"Fuel used: 600 / 100 × 6 = 36 litres. Cost: 36 × $2.00 = $72.00."},{"id":"m-rate-3-6","section":"math","domain":"psda","skill":"rate","level":3,"type":"mc","question":"A car uses 5 litres of fuel for every 100 kilometres. Fuel costs $1.25 per litre. What is the cost of the fuel for a 350-kilometre trip?","options":["$4.375","$17.5","$21.875","$43.75"],"answer":2,"explain":"Fuel used: 350 / 100 × 5 = 17.5 litres. Cost: 17.5 × $1.25 = $21.88."},{"id":"m-pct-1-3","section":"math","domain":"psda","skill":"pct","level":1,"type":"mc","question":"What is 20% of 360?","options":["72","288","720","1800"],"answer":0,"explain":"20% of 360 = 0.2 × 360 = 72."},{"id":"m-pct-1-4","section":"math","domain":"psda","skill":"pct","level":1,"type":"mc","question":"What is 20% of 160?","options":["32","128","320","800"],"answer":0,"explain":"20% of 160 = 0.2 × 160 = 32."},{"id":"m-pct-1-5","section":"math","domain":"psda","skill":"pct","level":1,"type":"mc","question":"What is 15% of 80?","options":["12","65","68","120"],"answer":0,"explain":"15% of 80 = 0.15 × 80 = 12."},{"id":"m-pct-1-6","section":"math","domain":"psda","skill":"pct","level":1,"type":"mc","question":"What is 20% of 120?","options":["24","96","240","600"],"answer":0,"explain":"20% of 120 = 0.2 × 120 = 24."},{"id":"m-pct-2-3","section":"math","domain":"psda","skill":"pct","level":2,"type":"mc","question":"The price of a jacket changed from $80 to $68. By what percent did the price decrease?","options":["12%","15%","17.6%","20%"],"answer":1,"explain":"Change = 12. Compare it with the original price: 12 / 80 = 0.15 = 15%."},{"id":"m-pct-2-4","section":"math","domain":"psda","skill":"pct","level":2,"type":"mc","question":"The price of a jacket changed from $150 to $195. By what percent did the price increase?","options":["23.1%","30%","35%","45%"],"answer":1,"explain":"Change = 45. Compare it with the original price: 45 / 150 = 0.3 = 30%."},{"id":"m-pct-2-5","section":"math","domain":"psda","skill":"pct","level":2,"type":"mc","question":"The price of a jacket changed from $250 to $300. By what percent did the price increase?","options":["16.7%","20%","25%","50%"],"answer":1,"explain":"Change = 50. Compare it with the original price: 50 / 250 = 0.2 = 20%."},{"id":"m-pct-2-6","section":"math","domain":"psda","skill":"pct","level":2,"type":"mc","question":"The price of a jacket changed from $80 to $32. By what percent did the price decrease?","options":["48%","60%","65%","150%"],"answer":1,"explain":"Change = 48. Compare it with the original price: 48 / 80 = 0.6 = 60%."},{"id":"m-pct-3-2","section":"math","domain":"psda","skill":"pct","level":3,"type":"mc","question":"A shop raises the price of a lamp by 10% and later lowers the new price by 10%. Compared with the original price, what is the overall change?","options":["An increase of 20%","An increase of 1%","No change","A decrease of 1%"],"answer":3,"explain":"Multiply the changes: 1.1 × 0.9 = 0.99. That is a decrease of 1% from the original price."},{"id":"m-pct-3-3","section":"math","domain":"psda","skill":"pct","level":3,"type":"mc","question":"A shop raises the price of a lamp by 50% and later lowers the new price by 20%. Compared with the original price, what is the overall change?","options":["An increase of 70%","An increase of 20%","An increase of 30%","A decrease of 20%"],"answer":1,"explain":"Multiply the changes: 1.5 × 0.8 = 1.2. That is an increase of 20% from the original price."},{"id":"m-pct-3-4","section":"math","domain":"psda","skill":"pct","level":3,"type":"mc","question":"After a 40% discount, a pair of shoes costs $48. What was the price before the discount?","options":["$67","$80","$88","$120"],"answer":1,"explain":"The sale price is 60% of the original: 0.6 × p = 48, so p = 48 / 0.6 = 80."},{"id":"m-pct-3-5","section":"math","domain":"psda","skill":"pct","level":3,"type":"mc","question":"After a 10% discount, a pair of shoes costs $36. What was the price before the discount?","options":["$40","$41","$46","$360"],"answer":0,"explain":"The sale price is 90% of the original: 0.9 × p = 36, so p = 36 / 0.9 = 40."},{"id":"m-pct-3-6","section":"math","domain":"psda","skill":"pct","level":3,"type":"mc","question":"After a 20% discount, a pair of shoes costs $48. What was the price before the discount?","options":["$58","$60","$68","$240"],"answer":1,"explain":"The sale price is 80% of the original: 0.8 × p = 48, so p = 48 / 0.8 = 60."},{"id":"m-stat-1-3","section":"math","domain":"psda","skill":"stat","level":1,"type":"mc","question":"What is the median of the data set 13, 27, 12, 20, 24, 29, 22?","options":["20","22","23","24"],"answer":1,"explain":"In order: 12, 13, 20, 22, 24, 27, 29. The middle (4th) value is 22."},{"id":"m-stat-1-4","section":"math","domain":"psda","skill":"stat","level":1,"type":"mc","question":"What is the median of the data set 4, 7, 14, 13, 12, 16, 10?","options":["10","11","12","13"],"answer":2,"explain":"In order: 4, 7, 10, 12, 13, 14, 16. The middle (4th) value is 12."},{"id":"m-stat-1-5","section":"math","domain":"psda","skill":"stat","level":1,"type":"mc","question":"What is the median of the data set 9, 8, 13, 15, 7, 22, 20?","options":["9","13","14","15"],"answer":1,"explain":"In order: 7, 8, 9, 13, 15, 20, 22. The middle (4th) value is 13."},{"id":"m-stat-1-6","section":"math","domain":"psda","skill":"stat","level":1,"type":"mc","question":"What is the median of the data set 11, 18, 13, 10, 29, 16, 5?","options":["10","11","13","16"],"answer":2,"explain":"In order: 5, 10, 11, 13, 16, 18, 29. The middle (4th) value is 13."},{"id":"m-stat-2-3","section":"math","domain":"psda","skill":"stat","level":2,"type":"spr","question":"The mean of five numbers is 11. Four of the numbers are 23, 4, 14, 9. What is the fifth number?","accept":["5"],"values":[5],"explain":"The five numbers add up to 5 × 11 = 55. The four given numbers add up to 50, so the fifth is 55 − 50 = 5."},{"id":"m-stat-2-4","section":"math","domain":"psda","skill":"stat","level":2,"type":"spr","question":"The mean of five numbers is 17. Four of the numbers are 15, 18, 9, 16. What is the fifth number?","accept":["27"],"values":[27],"explain":"The five numbers add up to 5 × 17 = 85. The four given numbers add up to 58, so the fifth is 85 − 58 = 27."},{"id":"m-stat-2-5","section":"math","domain":"psda","skill":"stat","level":2,"type":"spr","question":"The mean of five numbers is 13. Four of the numbers are 25, 7, 27, 5. What is the fifth number?","accept":["1"],"values":[1],"explain":"The five numbers add up to 5 × 13 = 65. The four given numbers add up to 64, so the fifth is 65 − 64 = 1."},{"id":"m-stat-2-6","section":"math","domain":"psda","skill":"stat","level":2,"type":"spr","question":"The mean of five numbers is 11. Four of the numbers are 14, 11, 19, 4. What is the fifth number?","accept":["7"],"values":[7],"explain":"The five numbers add up to 5 × 11 = 55. The four given numbers add up to 48, so the fifth is 55 − 48 = 7."},{"id":"m-stat-3-2","section":"math","domain":"psda","skill":"stat","level":3,"type":"mc","question":"The mean of 5 test scores is 26. When one more score is included, the mean of the 6 scores is 30. What is the score that was added?","options":["10","30","34","50"],"answer":3,"explain":"The first 5 scores total 5 × 26 = 130. All 6 total 6 × 30 = 180. The added score is 180 − 130 = 50."},{"id":"m-stat-3-3","section":"math","domain":"psda","skill":"stat","level":3,"type":"mc","question":"The mean of 4 test scores is 30. When one more score is included, the mean of the 5 scores is 32. What is the score that was added?","options":["24","32","34","40"],"answer":3,"explain":"The first 4 scores total 4 × 30 = 120. All 5 total 5 × 32 = 160. The added score is 160 − 120 = 40."},{"id":"m-stat-3-4","section":"math","domain":"psda","skill":"stat","level":3,"type":"mc","question":"The mean of 4 test scores is 13. When one more score is included, the mean of the 5 scores is 15. What is the score that was added?","options":["7","15","17","23"],"answer":3,"explain":"The first 4 scores total 4 × 13 = 52. All 5 total 5 × 15 = 75. The added score is 75 − 52 = 23."},{"id":"m-stat-3-5","section":"math","domain":"psda","skill":"stat","level":3,"type":"mc","question":"The mean of 4 test scores is 20. When one more score is included, the mean of the 5 scores is 23. What is the score that was added?","options":["11","23","26","35"],"answer":3,"explain":"The first 4 scores total 4 × 20 = 80. All 5 total 5 × 23 = 115. The added score is 115 − 80 = 35."},{"id":"m-stat-3-6","section":"math","domain":"psda","skill":"stat","level":3,"type":"mc","question":"The mean of 9 test scores is 12. When one more score is included, the mean of the 10 scores is 14. What is the score that was added?","options":["14","16","32","33"],"answer":2,"explain":"The first 9 scores total 9 × 12 = 108. All 10 total 10 × 14 = 140. The added score is 140 − 108 = 32."},{"id":"m-stat-2-7","section":"math","domain":"psda","skill":"stat","level":2,"type":"mc","question":"A data set consists of the values 15, 16, 19, 21, 22, 28, 120. The value 120 is removed. Which statement describes the effect on the mean and the median?","options":["Both the mean and the median decrease.","The mean stays the same and the median decreases.","The mean decreases and the median stays the same.","Both the mean and the median increase."],"answer":0,"explain":"Removing the largest value lowers the mean a lot (from about 34.4 to 20.2). The median moves from 21 to 20."},{"id":"m-stat-2-8","section":"math","domain":"psda","skill":"stat","level":2,"type":"mc","question":"A data set consists of the values 14, 15, 16, 23, 25, 28, 95. The value 95 is removed. Which statement describes the effect on the mean and the median?","options":["The mean stays the same and the median decreases.","The mean decreases and the median stays the same.","Both the mean and the median increase.","Both the mean and the median decrease."],"answer":3,"explain":"Removing the largest value lowers the mean a lot (from about 30.9 to 20.2). The median moves from 23 to 19.5."},{"id":"m-stat-2-9","section":"math","domain":"psda","skill":"stat","level":2,"type":"mc","question":"A data set consists of the values 20, 21, 24, 27, 28, 29, 95. The value 95 is removed. Which statement describes the effect on the mean and the median?","options":["The mean decreases and the median stays the same.","Both the mean and the median decrease.","Both the mean and the median increase.","The mean stays the same and the median decreases."],"answer":1,"explain":"Removing the largest value lowers the mean a lot (from about 34.9 to 24.8). The median moves from 27 to 25.5."},{"id":"m-stat-2-10","section":"math","domain":"psda","skill":"stat","level":2,"type":"mc","question":"A data set consists of the values 11, 14, 18, 22, 28, 29, 120. The value 120 is removed. Which statement describes the effect on the mean and the median?","options":["Both the mean and the median increase.","The mean decreases and the median stays the same.","The mean stays the same and the median decreases.","Both the mean and the median decrease."],"answer":3,"explain":"Removing the largest value lowers the mean a lot (from about 34.6 to 20.3). The median moves from 22 to 20."},{"id":"m-stat-2-11","section":"math","domain":"psda","skill":"stat","level":2,"type":"mc","question":"A data set consists of the values 14, 15, 17, 20, 23, 26, 80. The value 80 is removed. Which statement describes the effect on the mean and the median?","options":["Both the mean and the median decrease.","The mean stays the same and the median decreases.","Both the mean and the median increase.","The mean decreases and the median stays the same."],"answer":0,"explain":"Removing the largest value lowers the mean a lot (from about 27.9 to 19.2). The median moves from 20 to 18.5."},{"id":"m-stat-2-12","section":"math","domain":"psda","skill":"stat","level":2,"type":"mc","question":"A data set consists of the values 12, 15, 18, 20, 21, 23, 95. The value 95 is removed. Which statement describes the effect on the mean and the median?","options":["Both the mean and the median decrease.","The mean stays the same and the median decreases.","The mean decreases and the median stays the same.","Both the mean and the median increase."],"answer":0,"explain":"Removing the largest value lowers the mean a lot (from about 29.1 to 18.2). The median moves from 20 to 19."},{"id":"m-prob-1-3","section":"math","domain":"psda","skill":"prob","level":1,"type":"mc","question":"A bag holds 3 red, 8 blue and 4 green marbles. One marble is chosen at random. What is the probability that it is blue?","options":["1/5","4/15","8/7","8/15"],"answer":3,"explain":"There are 15 marbles and 8 are blue: 8/15."},{"id":"m-prob-1-4","section":"math","domain":"psda","skill":"prob","level":1,"type":"mc","question":"A bag holds 8 red, 3 blue and 9 green marbles. One marble is chosen at random. What is the probability that it is blue?","options":["9/20","3/20","2/5","3/17"],"answer":1,"explain":"There are 20 marbles and 3 are blue: 3/20."},{"id":"m-prob-1-5","section":"math","domain":"psda","skill":"prob","level":1,"type":"mc","question":"A bag holds 4 red, 8 blue and 2 green marbles. One marble is chosen at random. What is the probability that it is blue?","options":["4/7","2/7","4/3","1/7"],"answer":0,"explain":"There are 14 marbles and 8 are blue: 8/14 = 4/7."},{"id":"m-prob-1-6","section":"math","domain":"psda","skill":"prob","level":1,"type":"mc","question":"A bag holds 4 red, 7 blue and 6 green marbles. One marble is chosen at random. What is the probability that it is blue?","options":["6/17","7/10","7/17","4/17"],"answer":2,"explain":"There are 17 marbles and 7 are blue: 7/17."},{"id":"m-prob-2-3","section":"math","domain":"psda","skill":"prob","level":2,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If one of these students is chosen at random, what is the probability that the student walks to school?","options":["13/54","10/81","13/27","29/81"],"answer":2,"explain":"78 of the 162 students walk: 78/162 = 13/27.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","41","20","61"],["Grade 12","43","58","101"],["Total","84","78","162"]]}},{"id":"m-prob-2-4","section":"math","domain":"psda","skill":"prob","level":2,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If one of these students is chosen at random, what is the probability that the student walks to school?","options":["51/158","33/158","21/79","42/79"],"answer":3,"explain":"84 of the 158 students walk: 84/158 = 42/79.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","16","51","67"],["Grade 12","58","33","91"],["Total","74","84","158"]]}},{"id":"m-prob-2-5","section":"math","domain":"psda","skill":"prob","level":2,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If one of these students is chosen at random, what is the probability that the student walks to school?","options":["22/79","43/158","21/79","43/79"],"answer":3,"explain":"43 of the 79 students walk: 43/79.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","14","21","35"],["Grade 12","22","22","44"],["Total","36","43","79"]]}},{"id":"m-prob-2-6","section":"math","domain":"psda","skill":"prob","level":2,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If one of these students is chosen at random, what is the probability that the student walks to school?","options":["21/127","33/127","54/127","27/127"],"answer":2,"explain":"54 of the 127 students walk: 54/127.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","43","21","64"],["Grade 12","30","33","63"],["Total","73","54","127"]]}},{"id":"m-prob-3-2","section":"math","domain":"psda","skill":"prob","level":3,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If a Grade 12 student is chosen at random, what is the probability that the student walks to school?","options":["32/75","43/75","32/111","32/51"],"answer":0,"explain":"Look only at the Grade 12 row: 32 of the 75 Grade 12 students walk, so the probability is 32/75.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","17","19","36"],["Grade 12","43","32","75"],["Total","60","51","111"]]}},{"id":"m-prob-3-3","section":"math","domain":"psda","skill":"prob","level":3,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If a Grade 12 student is chosen at random, what is the probability that the student walks to school?","options":["23/60","37/56","37/103","37/60"],"answer":3,"explain":"Look only at the Grade 12 row: 37 of the 60 Grade 12 students walk, so the probability is 37/60.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","24","19","43"],["Grade 12","23","37","60"],["Total","47","56","103"]]}},{"id":"m-prob-3-4","section":"math","domain":"psda","skill":"prob","level":3,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If a Grade 12 student is chosen at random, what is the probability that the student walks to school?","options":["20/51","31/51","20/129","20/61"],"answer":0,"explain":"Look only at the Grade 12 row: 20 of the 51 Grade 12 students walk, so the probability is 20/51.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","37","41","78"],["Grade 12","31","20","51"],["Total","68","61","129"]]}},{"id":"m-prob-3-5","section":"math","domain":"psda","skill":"prob","level":3,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If a Grade 12 student is chosen at random, what is the probability that the student walks to school?","options":["1/4","41/94","41/62","53/94"],"answer":1,"explain":"Look only at the Grade 12 row: 41 of the 94 Grade 12 students walk, so the probability is 41/94.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","49","21","70"],["Grade 12","53","41","94"],["Total","102","62","164"]]}},{"id":"m-prob-3-6","section":"math","domain":"psda","skill":"prob","level":3,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If a Grade 12 student is chosen at random, what is the probability that the student walks to school?","options":["13/24","39/73","39/119","34/73"],"answer":1,"explain":"Look only at the Grade 12 row: 39 of the 73 Grade 12 students walk, so the probability is 39/73.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","13","33","46"],["Grade 12","34","39","73"],["Total","47","72","119"]]}},{"id":"m-infr-1-3","section":"math","domain":"psda","skill":"infr","level":1,"type":"mc","question":"In a random sample of 80 students at a school, 64 said they cycle to school. The school has 2,400 students. Based on the sample, what is the best estimate of the number of students at the school who cycle to school?","options":["64","480","1920","1984"],"answer":2,"explain":"64/80 of the sample cycle. Apply the same share to everyone: 64/80 × 2,400 = 1,920."},{"id":"m-infr-1-4","section":"math","domain":"psda","skill":"infr","level":1,"type":"mc","question":"In a random sample of 100 students at a school, 40 said they cycle to school. The school has 1,200 students. Based on the sample, what is the best estimate of the number of students at the school who cycle to school?","options":["40","480","520","720"],"answer":1,"explain":"40/100 of the sample cycle. Apply the same share to everyone: 40/100 × 1,200 = 480."},{"id":"m-infr-1-5","section":"math","domain":"psda","skill":"infr","level":1,"type":"mc","question":"In a random sample of 50 students at a school, 35 said they cycle to school. The school has 1,000 students. Based on the sample, what is the best estimate of the number of students at the school who cycle to school?","options":["35","300","700","735"],"answer":2,"explain":"35/50 of the sample cycle. Apply the same share to everyone: 35/50 × 1,000 = 700."},{"id":"m-infr-1-6","section":"math","domain":"psda","skill":"infr","level":1,"type":"mc","question":"In a random sample of 80 students at a school, 52 said they cycle to school. The school has 1,200 students. Based on the sample, what is the best estimate of the number of students at the school who cycle to school?","options":["52","420","780","832"],"answer":2,"explain":"52/80 of the sample cycle. Apply the same share to everyone: 52/80 × 1,200 = 780."},{"id":"m-infr-2-3","section":"math","domain":"psda","skill":"infr","level":2,"type":"mc","question":"A survey of a random sample of adults in the city estimated that 42% plan to vote in the election, with a margin of error of 3%. Which conclusion is best supported?","options":["At most 3% of all adults in the city gave an incorrect answer.","Exactly 42% of all adults in the city plan to vote in the election.","It is plausible that between 39% and 45% of all adults in the city plan to vote in the election.","Between 39% and 45% of the people in the sample plan to vote in the election."],"answer":2,"explain":"A margin of error describes how far the true share for the whole population may be from the sample result: about 39% to 45%."},{"id":"m-infr-2-4","section":"math","domain":"psda","skill":"infr","level":2,"type":"mc","question":"A survey of a random sample of adults in the city estimated that 62% plan to vote in the election, with a margin of error of 4%. Which conclusion is best supported?","options":["At most 4% of all adults in the city gave an incorrect answer.","Between 58% and 66% of the people in the sample plan to vote in the election.","It is plausible that between 58% and 66% of all adults in the city plan to vote in the election.","Exactly 62% of all adults in the city plan to vote in the election."],"answer":2,"explain":"A margin of error describes how far the true share for the whole population may be from the sample result: about 58% to 66%."},{"id":"m-infr-2-5","section":"math","domain":"psda","skill":"infr","level":2,"type":"mc","question":"A survey of a random sample of adults in the city estimated that 62% plan to vote in the election, with a margin of error of 3%. Which conclusion is best supported?","options":["At most 3% of all adults in the city gave an incorrect answer.","It is plausible that between 59% and 65% of all adults in the city plan to vote in the election.","Between 59% and 65% of the people in the sample plan to vote in the election.","Exactly 62% of all adults in the city plan to vote in the election."],"answer":1,"explain":"A margin of error describes how far the true share for the whole population may be from the sample result: about 59% to 65%."},{"id":"m-infr-2-6","section":"math","domain":"psda","skill":"infr","level":2,"type":"mc","question":"A survey of a random sample of residents of the town estimated that 54% support building a new library, with a margin of error of 3%. Which conclusion is best supported?","options":["Exactly 54% of all residents of the town support building a new library.","Between 51% and 57% of the people in the sample support building a new library.","It is plausible that between 51% and 57% of all residents of the town support building a new library.","At most 3% of all residents of the town gave an incorrect answer."],"answer":2,"explain":"A margin of error describes how far the true share for the whole population may be from the sample result: about 51% to 57%."},{"id":"m-infr-3-2","section":"math","domain":"psda","skill":"infr","level":3,"type":"mc","question":"In a study, 80 volunteers were randomly assigned to two groups. One group drank green tea every day for a month and the other did not. At the end, the tea group had lower average blood pressure. Which conclusion is best supported?","options":["Drinking green tea caused lower blood pressure for the volunteers in the study.","No conclusion about cause can be drawn, because the groups were assigned at random.","Drinking green tea lowers blood pressure for all people.","People with low blood pressure tend to choose green tea."],"answer":0,"explain":"Random assignment allows a cause-and-effect conclusion, but only about the people in the study. Volunteers are not a random sample of everyone."},{"id":"m-infr-3-3","section":"math","domain":"psda","skill":"infr","level":3,"type":"mc","question":"A researcher chose 80 students at random from all the Grade 9 students at one school and asked how long they sleep each night. To which group can the results best be generalised?","options":["All students at that school","Only the 80 students who were asked","All Grade 9 students at that school","All Grade 9 students in the country"],"answer":2,"explain":"A random sample speaks for the population it was drawn from: here, the Grade 9 students at that one school."},{"id":"m-infr-3-4","section":"math","domain":"psda","skill":"infr","level":3,"type":"mc","question":"A researcher chose 200 students at random from all the Grade 9 students at one school and asked how long they sleep each night. To which group can the results best be generalised?","options":["All Grade 9 students in the country","All students at that school","Only the 200 students who were asked","All Grade 9 students at that school"],"answer":3,"explain":"A random sample speaks for the population it was drawn from: here, the Grade 9 students at that one school."},{"id":"m-infr-3-5","section":"math","domain":"psda","skill":"infr","level":3,"type":"mc","question":"A researcher chose 120 students at random from all the Grade 10 students at one school and asked how long they sleep each night. To which group can the results best be generalised?","options":["All Grade 10 students in the country","All Grade 10 students at that school","Only the 120 students who were asked","All students at that school"],"answer":1,"explain":"A random sample speaks for the population it was drawn from: here, the Grade 10 students at that one school."},{"id":"m-infr-3-6","section":"math","domain":"psda","skill":"infr","level":3,"type":"mc","question":"A researcher chose 80 students at random from all the Grade 11 students at one school and asked how long they sleep each night. To which group can the results best be generalised?","options":["All Grade 11 students at that school","Only the 80 students who were asked","All students at that school","All Grade 11 students in the country"],"answer":0,"explain":"A random sample speaks for the population it was drawn from: here, the Grade 11 students at that one school."},{"id":"m-area-1-3","section":"math","domain":"geo","skill":"area","level":1,"type":"mc","question":"A triangle has a base of 8 centimetres and a height of 9 centimetres. What is its area, in square centimetres?","options":["17","34","36","72"],"answer":2,"explain":"Area = ½ × base × height = ½ × 8 × 9 = 36."},{"id":"m-area-1-4","section":"math","domain":"geo","skill":"area","level":1,"type":"mc","question":"A triangle has a base of 16 centimetres and a height of 5 centimetres. What is its area, in square centimetres?","options":["21","40","42","80"],"answer":1,"explain":"Area = ½ × base × height = ½ × 16 × 5 = 40."},{"id":"m-area-1-5","section":"math","domain":"geo","skill":"area","level":1,"type":"mc","question":"A triangle has a base of 12 centimetres and a height of 5 centimetres. What is its area, in square centimetres?","options":["17","30","34","60"],"answer":1,"explain":"Area = ½ × base × height = ½ × 12 × 5 = 30."},{"id":"m-area-1-6","section":"math","domain":"geo","skill":"area","level":1,"type":"mc","question":"A triangle has a base of 8 centimetres and a height of 5 centimetres. What is its area, in square centimetres?","options":["13","20","26","40"],"answer":1,"explain":"Area = ½ × base × height = ½ × 8 × 5 = 20."},{"id":"m-area-2-3","section":"math","domain":"geo","skill":"area","level":2,"type":"mc","question":"A rectangle has a perimeter of 42 metres and a length of 14 metres. What is its area, in square metres?","options":["7","98","392","588"],"answer":1,"explain":"Perimeter = 2(length + width), so 14 + width = 21 and width = 7. Area = 14 × 7 = 98."},{"id":"m-area-2-4","section":"math","domain":"geo","skill":"area","level":2,"type":"mc","question":"A right circular cylinder has a radius of 3 metres and a height of 5 metres. What is its volume, in cubic metres?","options":["45π","90π","15π","30π"],"answer":0,"explain":"Volume = πr²h = π × 9 × 5 = 45π."},{"id":"m-area-2-5","section":"math","domain":"geo","skill":"area","level":2,"type":"mc","question":"A rectangle has a perimeter of 48 metres and a length of 14 metres. What is its area, in square metres?","options":["10","140","476","672"],"answer":1,"explain":"Perimeter = 2(length + width), so 14 + width = 24 and width = 10. Area = 14 × 10 = 140."},{"id":"m-area-2-6","section":"math","domain":"geo","skill":"area","level":2,"type":"mc","question":"A rectangle has a perimeter of 28 metres and a length of 8 metres. What is its area, in square metres?","options":["6","48","160","224"],"answer":1,"explain":"Perimeter = 2(length + width), so 8 + width = 14 and width = 6. Area = 8 × 6 = 48."},{"id":"m-area-3-2","section":"math","domain":"geo","skill":"area","level":3,"type":"mc","question":"A cube has a volume of 15 cubic centimetres. A second cube has edges 3 times as long. What is the volume of the second cube, in cubic centimetres?","options":["45","135","405","406"],"answer":2,"explain":"When lengths are multiplied by 3, volumes are multiplied by 3³ = 27: 15 × 27 = 405."},{"id":"m-area-3-3","section":"math","domain":"geo","skill":"area","level":3,"type":"mc","question":"Rectangle A has an area of 8 square centimetres. Every side of rectangle B is 4 times as long as the matching side of rectangle A. What is the area of rectangle B, in square centimetres?","options":["24","32","64","128"],"answer":3,"explain":"When lengths are multiplied by 4, areas are multiplied by 4² = 16: 8 × 16 = 128."},{"id":"m-area-3-4","section":"math","domain":"geo","skill":"area","level":3,"type":"mc","question":"Rectangle A has an area of 15 square centimetres. Every side of rectangle B is 4 times as long as the matching side of rectangle A. What is the area of rectangle B, in square centimetres?","options":["31","60","120","240"],"answer":3,"explain":"When lengths are multiplied by 4, areas are multiplied by 4² = 16: 15 × 16 = 240."},{"id":"m-area-3-5","section":"math","domain":"geo","skill":"area","level":3,"type":"mc","question":"Rectangle A has an area of 15 square centimetres. Every side of rectangle B is 5 times as long as the matching side of rectangle A. What is the area of rectangle B, in square centimetres?","options":["40","75","150","375"],"answer":3,"explain":"When lengths are multiplied by 5, areas are multiplied by 5² = 25: 15 × 25 = 375."},{"id":"m-area-3-6","section":"math","domain":"geo","skill":"area","level":3,"type":"mc","question":"Rectangle A has an area of 20 square centimetres. Every side of rectangle B is 4 times as long as the matching side of rectangle A. What is the area of rectangle B, in square centimetres?","options":["36","80","160","320"],"answer":3,"explain":"When lengths are multiplied by 4, areas are multiplied by 4² = 16: 20 × 16 = 320."},{"id":"m-ang-1-3","section":"math","domain":"geo","skill":"ang","level":1,"type":"mc","question":"Two angles of a triangle measure 43° and 60°. What is the measure of the third angle?","options":["47°","77°","103°","257°"],"answer":1,"explain":"The angles of a triangle add up to 180°: 180 − 43 − 60 = 77."},{"id":"m-ang-1-4","section":"math","domain":"geo","skill":"ang","level":1,"type":"mc","question":"Two angles of a triangle measure 66° and 32°. What is the measure of the third angle?","options":["58°","82°","98°","262°"],"answer":1,"explain":"The angles of a triangle add up to 180°: 180 − 66 − 32 = 82."},{"id":"m-ang-1-5","section":"math","domain":"geo","skill":"ang","level":1,"type":"mc","question":"Two angles of a triangle measure 75° and 69°. What is the measure of the third angle?","options":["21°","36°","144°","216°"],"answer":1,"explain":"The angles of a triangle add up to 180°: 180 − 75 − 69 = 36."},{"id":"m-ang-1-6","section":"math","domain":"geo","skill":"ang","level":1,"type":"mc","question":"Two angles of a triangle measure 45° and 43°. What is the measure of the third angle?","options":["47°","88°","92°","272°"],"answer":2,"explain":"The angles of a triangle add up to 180°: 180 − 45 − 43 = 92."},{"id":"m-ang-2-3","section":"math","domain":"geo","skill":"ang","level":2,"type":"mc","question":"In an isosceles triangle, the angle between the two equal sides measures 52°. What is the measure of each of the other two angles?","options":["38°","52°","64°","128°"],"answer":2,"explain":"The other two angles are equal and together make 180 − 52 = 128°, so each is 64°."},{"id":"m-ang-2-4","section":"math","domain":"geo","skill":"ang","level":2,"type":"mc","question":"Two parallel lines are crossed by a third line. Two of the angles formed lie between the parallel lines, on the same side of the third line. One of them measures 118°. What is the measure of the other?","options":["28°","62°","118°","242°"],"answer":1,"explain":"Interior angles on the same side of a line crossing two parallel lines add up to 180°: 180 − 118 = 62."},{"id":"m-ang-2-5","section":"math","domain":"geo","skill":"ang","level":2,"type":"mc","question":"In an isosceles triangle, the angle between the two equal sides measures 100°. What is the measure of each of the other two angles?","options":["40°","80°","100°","130°"],"answer":0,"explain":"The other two angles are equal and together make 180 − 100 = 80°, so each is 40°."},{"id":"m-ang-2-6","section":"math","domain":"geo","skill":"ang","level":2,"type":"mc","question":"In an isosceles triangle, the angle between the two equal sides measures 40°. What is the measure of each of the other two angles?","options":["40°","50°","70°","140°"],"answer":2,"explain":"The other two angles are equal and together make 180 − 40 = 140°, so each is 70°."},{"id":"m-ang-3-2","section":"math","domain":"geo","skill":"ang","level":3,"type":"spr","question":"Triangle ABC is similar to triangle DEF, with A matching D, B matching E and C matching F. AB = 5, BC = 8 and DE = 15. What is the length of EF?","accept":["24"],"values":[24],"explain":"The scale factor is DE / AB = 15 / 5 = 3. So EF = 3 × BC = 3 × 8 = 24."},{"id":"m-ang-3-3","section":"math","domain":"geo","skill":"ang","level":3,"type":"spr","question":"Triangle ABC is similar to triangle DEF, with A matching D. The sides of triangle ABC are 5, 6 and 7. The shortest side of triangle DEF is 10. What is the perimeter of triangle DEF?","accept":["36"],"values":[36],"explain":"The scale factor is 10 / 5 = 2. Perimeters scale the same way: 2 × (5 + 6 + 7) = 36."},{"id":"m-ang-3-4","section":"math","domain":"geo","skill":"ang","level":3,"type":"spr","question":"Triangle ABC is similar to triangle DEF, with A matching D. The sides of triangle ABC are 5, 8 and 10. The shortest side of triangle DEF is 7.5. What is the perimeter of triangle DEF?","accept":["34.5"],"values":[34.5],"explain":"The scale factor is 7.5 / 5 = 1.5. Perimeters scale the same way: 1.5 × (5 + 8 + 10) = 34.5."},{"id":"m-ang-3-5","section":"math","domain":"geo","skill":"ang","level":3,"type":"spr","question":"Triangle ABC is similar to triangle DEF, with A matching D. The sides of triangle ABC are 5, 8 and 10. The shortest side of triangle DEF is 10. What is the perimeter of triangle DEF?","accept":["46"],"values":[46],"explain":"The scale factor is 10 / 5 = 2. Perimeters scale the same way: 2 × (5 + 8 + 10) = 46."},{"id":"m-ang-3-6","section":"math","domain":"geo","skill":"ang","level":3,"type":"spr","question":"Triangle ABC is similar to triangle DEF, with A matching D. The sides of triangle ABC are 5, 6 and 7. The shortest side of triangle DEF is 15. What is the perimeter of triangle DEF?","accept":["54"],"values":[54],"explain":"The scale factor is 15 / 5 = 3. Perimeters scale the same way: 3 × (5 + 6 + 7) = 54."},{"id":"m-trig-1-3","section":"math","domain":"geo","skill":"trig","level":1,"type":"mc","question":"A right triangle has a hypotenuse of length 29 and one leg of length 20. What is the length of the other leg?","options":["9","20","21","49"],"answer":2,"explain":"b² = 29² − 20² = 841 − 400 = 441, so b = 21."},{"id":"m-trig-1-4","section":"math","domain":"geo","skill":"trig","level":1,"type":"mc","question":"A right triangle has legs of length 9 and 12. What is the length of its hypotenuse?","options":["15","18","21","54"],"answer":0,"explain":"c² = 9² + 12² = 81 + 144 = 225, so c = 15."},{"id":"m-trig-1-5","section":"math","domain":"geo","skill":"trig","level":1,"type":"mc","question":"A right triangle has legs of length 6 and 8. What is the length of its hypotenuse?","options":["10","12","14","24"],"answer":0,"explain":"c² = 6² + 8² = 36 + 64 = 100, so c = 10."},{"id":"m-trig-1-6","section":"math","domain":"geo","skill":"trig","level":1,"type":"mc","question":"A right triangle has a hypotenuse of length 15 and one leg of length 9. What is the length of the other leg?","options":["6","9","12","24"],"answer":2,"explain":"b² = 15² − 9² = 225 − 81 = 144, so b = 12."},{"id":"m-trig-2-3","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In right triangle PQR, the right angle is at Q. PQ = 24, QR = 7 and PR = 25. What is the value of sin P?","options":["24/7","24/25","7/24","7/25"],"answer":3,"explain":"For angle P the opposite side is QR = 7, the adjacent side is PQ = 24 and the hypotenuse is PR = 25. sin P = 7/25."},{"id":"m-trig-2-4","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In right triangle PQR, the right angle is at Q. PQ = 12, QR = 5 and PR = 13. What is the value of sin P?","options":["12/13","5/13","12/5","5/12"],"answer":1,"explain":"For angle P the opposite side is QR = 5, the adjacent side is PQ = 12 and the hypotenuse is PR = 13. sin P = 5/13."},{"id":"m-trig-2-5","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In right triangle PQR, the right angle is at Q. PQ = 21, QR = 20 and PR = 29. What is the value of tan P?","options":["20/29","20/21","21/29","21/20"],"answer":1,"explain":"For angle P the opposite side is QR = 20, the adjacent side is PQ = 21 and the hypotenuse is PR = 29. tan P = 20/21."},{"id":"m-trig-2-6","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In right triangle PQR, the right angle is at Q. PQ = 24, QR = 7 and PR = 25. What is the value of cos P?","options":["7/25","24/7","24/25","7/24"],"answer":2,"explain":"For angle P the opposite side is QR = 7, the adjacent side is PQ = 24 and the hypotenuse is PR = 25. cos P = 24/25."},{"id":"m-trig-2-7","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In a right triangle with angles of 30°, 60° and 90°, the hypotenuse has length 16. What is the length of the side opposite the 60° angle?","options":["8","8√2","16√3","8√3"],"answer":3,"explain":"In a 30-60-90 triangle the sides are in the ratio 1 : √3 : 2. The hypotenuse is 16, so the short leg is 8 and the side opposite 60° is 8√3."},{"id":"m-trig-2-8","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"A right triangle has two legs of length 6. What is the length of its hypotenuse?","options":["36","6√2","12","6√3"],"answer":1,"explain":"c² = 6² + 6² = 72, so c = √72 = 6√2."},{"id":"m-trig-2-9","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In a right triangle with angles of 30°, 60° and 90°, the hypotenuse has length 6. What is the length of the side opposite the 60° angle?","options":["3","3√3","6√3","3√2"],"answer":1,"explain":"In a 30-60-90 triangle the sides are in the ratio 1 : √3 : 2. The hypotenuse is 6, so the short leg is 3 and the side opposite 60° is 3√3."},{"id":"m-trig-2-10","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"A right triangle has two legs of length 5. What is the length of its hypotenuse?","options":["5√3","10","25","5√2"],"answer":3,"explain":"c² = 5² + 5² = 50, so c = √50 = 5√2."},{"id":"m-trig-2-11","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"A right triangle has two legs of length 9. What is the length of its hypotenuse?","options":["81","9√2","9√3","18"],"answer":1,"explain":"c² = 9² + 9² = 162, so c = √162 = 9√2."},{"id":"m-trig-2-12","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"A right triangle has two legs of length 7. What is the length of its hypotenuse?","options":["49","14","7√2","7√3"],"answer":2,"explain":"c² = 7² + 7² = 98, so c = √98 = 7√2."},{"id":"m-trig-3-2","section":"math","domain":"geo","skill":"trig","level":3,"type":"mc","question":"In right triangle ABC, the right angle is at C. If sin A = 8/17, what is the value of cos B?","options":["8/17","17/8","8/15","15/17"],"answer":0,"explain":"A and B are the two acute angles, so they add up to 90°. The cosine of B equals the sine of A: 8/17."},{"id":"m-trig-3-3","section":"math","domain":"geo","skill":"trig","level":3,"type":"spr","question":"For an angle of x degrees, where 0 < x < 90, sin(x°) = cos(71°). What is the value of x?","accept":["19"],"values":[19],"explain":"The sine of an angle equals the cosine of its complement, so x + 71 = 90 and x = 19."},{"id":"m-trig-3-4","section":"math","domain":"geo","skill":"trig","level":3,"type":"spr","question":"For an angle of x degrees, where 0 < x < 90, sin(x°) = cos(62°). What is the value of x?","accept":["28"],"values":[28],"explain":"The sine of an angle equals the cosine of its complement, so x + 62 = 90 and x = 28."},{"id":"m-trig-3-5","section":"math","domain":"geo","skill":"trig","level":3,"type":"spr","question":"For an angle of x degrees, where 0 < x < 90, sin(x°) = cos(23°). What is the value of x?","accept":["67"],"values":[67],"explain":"The sine of an angle equals the cosine of its complement, so x + 23 = 90 and x = 67."},{"id":"m-trig-3-6","section":"math","domain":"geo","skill":"trig","level":3,"type":"mc","question":"In right triangle ABC, the right angle is at C. If sin A = 3/5, what is the value of cos B?","options":["5/3","4/5","3/4","3/5"],"answer":3,"explain":"A and B are the two acute angles, so they add up to 90°. The cosine of B equals the sine of A: 3/5."},{"id":"m-circ-1-3","section":"math","domain":"geo","skill":"circ","level":1,"type":"mc","question":"A circle has a diameter of 16 centimetres. What is its circumference, in centimetres?","options":["16π","32π","64π","8π"],"answer":0,"explain":"Circumference = π × diameter = 16π."},{"id":"m-circ-1-4","section":"math","domain":"geo","skill":"circ","level":1,"type":"mc","question":"A circle has a radius of 5 centimetres. What is its area, in square centimetres?","options":["100π","10π","5π","25π"],"answer":3,"explain":"Area = πr² = π × 5² = 25π."},{"id":"m-circ-1-5","section":"math","domain":"geo","skill":"circ","level":1,"type":"mc","question":"A circle has a diameter of 18 centimetres. What is its circumference, in centimetres?","options":["36π","18π","9π","81π"],"answer":1,"explain":"Circumference = π × diameter = 18π."},{"id":"m-circ-1-6","section":"math","domain":"geo","skill":"circ","level":1,"type":"mc","question":"A circle has a diameter of 14 centimetres. What is its circumference, in centimetres?","options":["14π","49π","28π","7π"],"answer":0,"explain":"Circumference = π × diameter = 14π."},{"id":"m-circ-2-3","section":"math","domain":"geo","skill":"circ","level":2,"type":"mc","question":"In a circle with a radius of 12, a central angle of 45° cuts off an arc. What is the length of the arc?","options":["18π","6π","3/2π","3π"],"answer":3,"explain":"The arc is 45/360 = 1/8 of the circumference, 24π: 1/8 × 24π = 3π."},{"id":"m-circ-2-4","section":"math","domain":"geo","skill":"circ","level":2,"type":"mc","question":"In a circle with a radius of 8, a central angle of 90° cuts off an arc. What is the length of the arc?","options":["4π","8π","16π","2π"],"answer":0,"explain":"The arc is 90/360 = 1/4 of the circumference, 16π: 1/4 × 16π = 4π."},{"id":"m-circ-2-5","section":"math","domain":"geo","skill":"circ","level":2,"type":"mc","question":"In the xy-plane, a circle has the equation (x − 2)² + (y + 3)² = 36. What is the centre of the circle?","options":["(−3, 2)","(−2, 3)","(2, −3)","(−2, −3)"],"answer":2,"explain":"In (x − h)² + (y − k)² = r² the centre is (h, k). Here that is (2, −3), and the radius is 6."},{"id":"m-circ-2-6","section":"math","domain":"geo","skill":"circ","level":2,"type":"mc","question":"In the xy-plane, a circle has the equation (x + 2)² + (y + 4)² = 81. What is the centre of the circle?","options":["(−2, −4)","(2, 4)","(2, −4)","(−4, −2)"],"answer":0,"explain":"In (x − h)² + (y − k)² = r² the centre is (h, k). Here that is (−2, −4), and the radius is 9."},{"id":"m-circ-3-2","section":"math","domain":"geo","skill":"circ","level":3,"type":"spr","question":"x² + y² − 10x + 4y + 25 = 0\n\nThe equation above represents a circle in the xy-plane. What is the radius of the circle?","accept":["2"],"values":[2],"explain":"Complete the square for x and for y: (x − 5)² + (y + 2)² = −25 + 25 + 4 = 4. The radius is √4 = 2."},{"id":"m-circ-3-3","section":"math","domain":"geo","skill":"circ","level":3,"type":"mc","question":"An angle measures 120°. What is its measure in radians?","options":["3π/2","4π/3","π/3","2π/3"],"answer":3,"explain":"Multiply by π/180: 120 × π/180 = 2π/3."},{"id":"m-circ-3-4","section":"math","domain":"geo","skill":"circ","level":3,"type":"spr","question":"x² + y² + 2x − 2y − 47 = 0\n\nThe equation above represents a circle in the xy-plane. What is the radius of the circle?","accept":["7"],"values":[7],"explain":"Complete the square for x and for y: (x + 1)² + (y − 1)² = 47 + 1 + 1 = 49. The radius is √49 = 7."},{"id":"m-circ-3-5","section":"math","domain":"geo","skill":"circ","level":3,"type":"spr","question":"x² + y² + 6x − 2y − 6 = 0\n\nThe equation above represents a circle in the xy-plane. What is the radius of the circle?","accept":["4"],"values":[4],"explain":"Complete the square for x and for y: (x + 3)² + (y − 1)² = 6 + 9 + 1 = 16. The radius is √16 = 4."},{"id":"m-circ-3-6","section":"math","domain":"geo","skill":"circ","level":3,"type":"mc","question":"An angle measures 315°. What is its measure in radians?","options":["4π/7","7π/8","7π/2","7π/4"],"answer":3,"explain":"Multiply by π/180: 315 × π/180 = 7π/4."}];
